    .equ ARCADE_ROM_BASE, 0x00000200
    .equ PC090OJ_HW_BASE, 0x00D00000
    /* Active mirrored HW window tracks the configured record count so that when
     * PC090OJ_MIRROR_RECORDS < 256 the address-based mirror writers reject
     * out-of-range records instead of overflowing the smaller mirror array. */
    .equ PC090OJ_HW_ACTIVE_END, (PC090OJ_HW_BASE + PC090OJ_MIRROR_BYTES)
    /* Arcade A5 work-RAM base.  Absolute arcade work-RAM pointers (0x0010Cxxx)
     * map to Genesis WRAM as a5 + (pointer - ARCADE_WORKRAM_A5_BASE); the Genesis
     * a5 (0x00FF0000) corresponds to this arcade base (arcade 0x0010C000 ->
     * Genesis 0x00FF0000, e.g. the ranking table names at 0x00FF0157). */
    .equ ARCADE_WORKRAM_A5_BASE, 0x0010C000
    /* Arcade 0x59F5E clears 8 PC090OJ records starting at HW 0x00D00048
     * (= PC090OJ_HW_BASE + record 9), i.e. records 9..16.  It never touches the
     * HIGH SCORE label records 4..8.  (Build 0149 fix: the translation cleared
     * records 0..7, wiping label records 4..7 on coin insertion -> only "RE"
     * remained above 273100.) */
    .equ HOOK_59F5E_CLEAR_FIRST_RECORD, 9   /* (0x00D00048 - PC090OJ_HW_BASE) / 8 */
    .equ HOOK_59F5E_CLEAR_RECORD_COUNT, 8
    .equ PC090OJ_BLOCK2C8_BASE_RECORD, 140
    .equ PC090OJ_BLOCK2C8_APPLIED_RECORDS, (8 * 10 + 19)
    .equ PC090OJ_BLOCK2C8_SCRATCH_RECORDS, 100
    .equ PC090OJ_BLOCK2C8_SCRATCH_BYTES, (PC090OJ_BLOCK2C8_SCRATCH_RECORDS * 8)
    .if PC090OJ_BLOCK2C8_APPLIED_RECORDS > PC090OJ_BLOCK2C8_SCRATCH_RECORDS
    .error "block A5+0x2C8 scratch too small"
    .endif
    .if (PC090OJ_BLOCK2C8_BASE_RECORD + PC090OJ_BLOCK2C8_APPLIED_RECORDS - 1) != 238
    .error "block A5+0x2C8 record span must end at record 238"
    .endif

    /* ------------------------------------------------------------------ *
     * Build 0147: PC090OJ viewport coordinate + opaque-clip constants.   *
     * Named so sprite/background alignment is easy to read and to tune   *
     * during later emulator, gameplay, and real-CRT testing.             *
     * ------------------------------------------------------------------ */
    /* 16x16 sprite cell geometry. */
    .equ PC090OJ_PATTERN_WIDTH,   16
    .equ PC090OJ_PATTERN_HEIGHT,  16
    .equ PC090OJ_PATTERN_MAX_ROW, 15    /* PC090OJ_PATTERN_HEIGHT - 1 */
    .equ PC090OJ_PATTERN_MAX_COL, 15    /* PC090OJ_PATTERN_WIDTH  - 1 */
    /* Arcade PC090OJ non-flipped coordinate inversion (MAME taito/pc090oj.cpp:
     * x = 320 - x - 16, y = 256 - y - 16 when the flip-screen ctrl bit is clear). */
    .equ PC090OJ_FLIP_X_TERM, 304       /* 320 - PC090OJ_PATTERN_WIDTH  */
    .equ PC090OJ_FLIP_Y_TERM, 240       /* 256 - PC090OJ_PATTERN_HEIGHT */
    .equ PC090OJ_TO_GENESIS_X_OFFSET,  0   /* frontend X already aligned; tune later */
    .equ PC090OJ_TO_GENESIS_Y_OFFSET, -8   /* remove top 8 arcade lines */
    /* Effective sprite clip rectangle = intersection of the arcade visible area
     * (raster 8..247 -> Genesis 0..239 after the Y origin) and the Genesis output
     * viewport (0..223, 0..319).  The Genesis bounds bind; ends are exclusive. */
    .equ GENESIS_VIEWPORT_LEFT,   0
    .equ GENESIS_VIEWPORT_RIGHT,  320
    .equ GENESIS_VIEWPORT_TOP,    0
    .equ GENESIS_VIEWPORT_BOTTOM, 224
    /* Genesis SAT coordinate biases (SAT value = screen coord + bias). */
    .equ PC090OJ_SAT_Y_BIAS, 0x80
    .equ PC090OJ_SAT_X_BIAS, 0x80

