.Lhook_45dfa_gameplay_native:
    bsr     native_stage_dispatch_45dfa
    bsr     pc090oj_native_emit_pass
    rts


/* Build 0250 native gameplay sprite lanes.  These queues are semantic output
 * lanes, not PC090OJ object RAM: producers append visible 16x16 pieces and the
 * finalizer later concatenates them into one Genesis SAT chain.  Legacy mirror
 * code remains physically present for frontend/non-gameplay comparison only. */
native_sprite_frame_begin:
    /* arcade 0x5A098 publishes the persistent gameplay energy/status lane
     * before this frame boundary.  It owns refresh/retention of that lane;
     * clearing it here would discard the native status output before the
     * gameplay finalizer can consume it. */
    clr.w   native_front_effect_count
    clr.w   native_middle_count
    clr.w   native_back_enemy_count
    clr.w   pc090oj_sat_frame_ready
    rts

/* Main-loop player producers own these two completed semantic lanes.  Reset
 * once before arcade 0x51060 (FRONT), then BODY appends later at 0x5151C. */
native_player_frame_begin:
    clr.w   native_player_front_count
    clr.w   native_player_body_count
    rts

native_player_front_begin:
    move.b  #NATIVE_LANE_PLAYER_FRONT, native_sprite_lane+1
    rts

/* Whole fixed-FRONT semantic producer.  Replaces arcade 0x59F92 at function
 * entry: the four invariant records are generated directly from their three
 * retained active/type fields, with no PC090OJ tuple and no per-piece adapter. */
native_player_front_fixed:
    movem.l %d0-%d4/%a0-%a3/%a6, -(%sp)
    move.b  #NATIVE_LANE_PLAYER_FRONT, native_sprite_lane+1
    bsr     native_sprite_fast_context

    move.w  0x1388(%a5), %d0
    cmpi.w  #3, %d0
    bhi.s   .Lnpff_overlay1
    moveq   #3, %d1
    move.w  #0x00E8, %d2
    move.w  #0x0A6A, %d3
    add.w   %d0, %d3
    move.w  #0x00A0, %d4
    bsr     native_sprite_emit_fast
.Lnpff_overlay1:
    cmpi.w  #0x00FF, 0x140E(%a5)
    beq.s   .Lnpff_overlay2
    move.w  #0x0080, %d1
    move.w  #0x00E8, %d2
    move.w  #0x0A68, %d3
    move.w  #0x00B0, %d4
    bsr     native_sprite_emit_fast
.Lnpff_overlay2:
    cmpi.w  #0x00FF, 0x1410(%a5)
    beq.s   .Lnpff_overlay3
    move.w  #0x0080, %d1
    move.w  #0x00E8, %d2
    move.w  #0x0A66, %d3
    move.w  #0x00C0, %d4
    bsr     native_sprite_emit_fast
.Lnpff_overlay3:
    cmpi.w  #0x00FF, 0x140C(%a5)
    beq.s   .Lnpff_done
    move.w  #0x0080, %d1
    move.w  #0x00E8, %d2
    move.w  #0x0A64, %d3
    move.w  #0x00D0, %d4
    bsr     native_sprite_emit_fast
.Lnpff_done:
    movem.l (%sp)+, %d0-%d4/%a0-%a3/%a6
    rts

/* Whole fixed three-piece auxiliary producer at arcade 0x5474E.  The retained
 * gameplay-owned A5+0x1338 records supply only active/Y/X; code animation is
 * the original A5+0x1364 phase. */
native_player_aux_fixed:
    movem.l %d0-%d4/%d7/%a0-%a3/%a6, -(%sp)
    move.b  #NATIVE_LANE_PLAYER_BODY, native_sprite_lane+1
    bsr     native_sprite_fast_context
    lea     0x1338(%a5), %a0
    moveq   #2, %d7
.Lnpaf_loop:
    cmpi.w  #0x00FF, (%a0)
    beq.s   .Lnpaf_next
    move.w  #0x0010, %d1
    move.w  4(%a0), %d2
    move.w  #0x09D9, %d3
    add.w   0x1364(%a5), %d3
    move.w  2(%a0), %d4
    bsr     native_sprite_emit_fast
.Lnpaf_next:
    addq.l  #8, %a0
    dbra    %d7, .Lnpaf_loop
    addq.w  #1, 0x1364(%a5)
    cmpi.w  #3, 0x1364(%a5)
    bne.s   .Lnpaf_done
    clr.w   0x1364(%a5)
.Lnpaf_done:
    movem.l (%sp)+, %d0-%d4/%d7/%a0-%a3/%a6
    rts

native_player_body_begin:
    move.b  #NATIVE_LANE_PLAYER_BODY, native_sprite_lane+1
    rts

/* Native Graphics Task 1, dedicated player-compositor pilot.
 *
 * Called at the semantic entry to arcade 0x54492 after 0x54326 has selected
 * A5+0x1244.  D0.b=1 means this routine emitted the complete primary-body plus
 * static weapon overlay and the caller must return from 0x54492.  D0.b=0 means
 * UNRESOLVED and the retained Build-0400 compositor must continue unchanged.
 *
 * Key = ((effective A5+0x1244 * 5 + A5+0x12FA) * 2 + orientation), where
 * orientation 0 is A5+0x1114==2 and 1 is every mirrored orientation.  Mode 9,
 * orientation value 3 retains the original selector decrement here. */
native_player_frame_try:
    movem.l %d1-%d7/%a0-%a3/%a6, -(%sp)
    moveq   #0, %d0
    move.w  0x1244(%a5), %d0
    cmpi.w  #9, 0x10E8(%a5)
    bne.s   .Lnpft_selector_ready
    cmpi.w  #3, 0x1114(%a5)
    bne.s   .Lnpft_selector_ready
    subq.w  #1, %d0
.Lnpft_selector_ready:
    cmpi.w  #74, %d0
    bhi     .Lnpft_unresolved
    moveq   #0, %d1
    move.w  0x12FA(%a5), %d1
    cmpi.w  #4, %d1
    bhi     .Lnpft_unresolved
    cmpi.w  #4, %d1
    bne.s   .Lnpft_variant_ready
    move.w  0x1308(%a5), %d1          /* finite fire-sword phase */
    lsr.w   #1, %d1
    andi.w  #3, %d1
    addq.w  #4, %d1
.Lnpft_variant_ready:
    mulu.w  #8, %d0
    add.w   %d1, %d0
    add.w   %d0, %d0
    cmpi.w  #2, 0x1114(%a5)
    beq.s   .Lnpft_key_ready
    addq.w  #1, %d0
.Lnpft_key_ready:
    mulu.w  #12, %d0
    lea     pc090oj_player_frame_index, %a1
    adda.l  %d0, %a1
    move.l  (%a1), %d0
    cmpi.l  #0xFFFFFFFF, %d0
    beq     .Lnpft_unresolved
    moveq   #0, %d7
    move.b  4(%a1), %d7
    moveq   #0, %d4
    move.b  5(%a1), %d4
    cmpi.b  #1, %d4
    beq.s   .Lnpft_format_ready
    cmpi.b  #2, %d4
    bne     .Lnpft_unresolved
.Lnpft_format_ready:
    move.w  6(%a1), %d1              /* frame-wide attr for compact format */
    lea     pc090oj_player_piece_table, %a0
    adda.l  %d0, %a0

    move.b  #NATIVE_LANE_PLAYER_BODY, native_sprite_lane+1
    bsr     native_sprite_fast_context
    clr.w   0x129A(%a5)
    clr.w   0x129C(%a5)
    move.w  0x10BE(%a5), %d5          /* player base X */
    move.w  0x10C0(%a5), %d6          /* player base Y */
    move.w  8(%a1), %d2               /* generated weapon-anchor dx */
    cmpi.w  #0x8000, %d2
    beq.s   .Lnpft_anchor_done
    add.w   %d5, %d2
    andi.w  #0x01FF, %d2
    move.w  %d2, 0x129A(%a5)
    move.w  10(%a1), %d2              /* generated weapon-anchor dy */
    add.w   %d6, %d2
    andi.w  #0x01FF, %d2
    move.w  %d2, 0x129C(%a5)
.Lnpft_anchor_done:
    tst.w   %d7
    beq.s   .Lnpft_native_done
    move.w  (%a6), %d0                /* establish append cursor once */
    lsl.w   #3, %d0
    lea     0(%a3,%d0.w), %a1
    cmpi.b  #2, %d4
    beq.s   .Lnpft_mixed_piece_loop
.Lnpft_compact_piece_loop:
    move.w  0(%a0), %d4
    add.w   %d5, %d4
    move.w  2(%a0), %d2
    add.w   %d6, %d2
    move.w  4(%a0), %d3               /* baked finalized vi == non-divergent code */
    move.w  %d2, %d0                  /* retained Y visibility test */
    andi.w  #0x01FF, %d0
    cmpi.w  #0x0180, %d0
    beq.s   .Lnpft_compact_next
    cmpa.l  %a2, %a1
    bhs.s   .Lnpft_native_done
    move.w  %d1, (%a1)+
    move.w  %d2, (%a1)+
    move.w  %d3, (%a1)+
    move.w  %d4, (%a1)+
    addq.w  #1, (%a6)
.Lnpft_compact_next:
    adda.w  #6, %a0
    subq.w  #1, %d7
    bne.s   .Lnpft_compact_piece_loop
    bra.s   .Lnpft_native_done
.Lnpft_mixed_piece_loop:
    move.w  0(%a0), %d4
    add.w   %d5, %d4
    move.w  2(%a0), %d2
    add.w   %d6, %d2
    move.w  4(%a0), %d3
    move.w  6(%a0), %d1               /* only 28 keys genuinely vary by piece */
    move.w  %d2, %d0
    andi.w  #0x01FF, %d0
    cmpi.w  #0x0180, %d0
    beq.s   .Lnpft_mixed_next
    cmpa.l  %a2, %a1
    bhs.s   .Lnpft_native_done
    move.w  %d1, (%a1)+
    move.w  %d2, (%a1)+
    move.w  %d3, (%a1)+
    move.w  %d4, (%a1)+
    addq.w  #1, (%a6)
.Lnpft_mixed_next:
    adda.w  #8, %a0
    subq.w  #1, %d7
    bne.s   .Lnpft_mixed_piece_loop
.Lnpft_native_done:
    movem.l (%sp)+, %d1-%d7/%a0-%a3/%a6
    moveq   #1, %d0
    rts
.Lnpft_unresolved:
    addq.w  #1, native_player_fallback_count
    movem.l (%sp)+, %d1-%d7/%a0-%a3/%a6
    moveq   #0, %d0
    rts

/* Whole A5+0x1246 secondary/legs compositor.  Replaces arcade 0x546A8 at
 * its semantic entry.  Python has already decoded the 0x5C466 descriptor
 * table, finite A5+0x1308 substitutions, and both mirror orientations. */
native_player_secondary_frame:
    movem.l %d0-%d7/%a0-%a3/%a6, -(%sp)
    moveq   #0, %d0
    move.w  0x1246(%a5), %d0
    cmpi.w  #9, 0x10E8(%a5)
    bne.s   .Lnpsf_selector_ready
    cmpi.w  #3, 0x1114(%a5)
    bne.s   .Lnpsf_selector_ready
    subq.w  #1, %d0
.Lnpsf_selector_ready:
    cmpi.w  #51, %d0
    bhi     .Lnpsf_unresolved
    move.w  0x1308(%a5), %d1
    lsr.w   #1, %d1
    andi.w  #3, %d1
    mulu.w  #4, %d0
    add.w   %d1, %d0
    add.w   %d0, %d0
    cmpi.w  #2, 0x1114(%a5)
    beq.s   .Lnpsf_key_ready
    addq.w  #1, %d0
.Lnpsf_key_ready:
    mulu.w  #12, %d0
    lea     pc090oj_secondary_frame_index, %a1
    adda.l  %d0, %a1
    move.l  (%a1), %d0
    moveq   #0, %d7
    move.b  4(%a1), %d7
    cmpi.b  #1, 5(%a1)
    bne.s   .Lnpsf_unresolved
    move.w  6(%a1), %d1              /* all secondary attrs are frame-wide */
    lea     pc090oj_player_piece_table, %a0
    adda.l  %d0, %a0
    move.b  #NATIVE_LANE_PLAYER_BODY, native_sprite_lane+1
    bsr     native_sprite_fast_context
    move.w  0x10BE(%a5), %d5
    move.w  0x10C0(%a5), %d6
    tst.w   %d7
    beq.s   .Lnpsf_done
    move.w  (%a6), %d0
    lsl.w   #3, %d0
    lea     0(%a3,%d0.w), %a1
.Lnpsf_piece_loop:
    move.w  0(%a0), %d4
    add.w   %d5, %d4
    move.w  2(%a0), %d2
    add.w   %d6, %d2
    move.w  4(%a0), %d3
    move.w  %d2, %d0
    andi.w  #0x01FF, %d0
    cmpi.w  #0x0180, %d0
    beq.s   .Lnpsf_next
    cmpa.l  %a2, %a1
    bhs.s   .Lnpsf_done
    move.w  %d1, (%a1)+
    move.w  %d2, (%a1)+
    move.w  %d3, (%a1)+
    move.w  %d4, (%a1)+
    addq.w  #1, (%a6)
.Lnpsf_next:
    adda.w  #6, %a0
    subq.w  #1, %d7
    bne.s   .Lnpsf_piece_loop
.Lnpsf_done:
    movem.l (%sp)+, %d0-%d7/%a0-%a3/%a6
    rts
.Lnpsf_unresolved:
    addq.w  #1, native_player_fallback_count
    movem.l (%sp)+, %d0-%d7/%a0-%a3/%a6
    rts

native_player_body_anchor_blank:
    cmpi.w  #4, %d2
    bne.s   .Lnative_player_anchor_blank_done
    clr.w   0x129A(%a5)
    clr.w   0x129C(%a5)
.Lnative_player_anchor_blank_done:
    rts

native_player_body_anchor_clear:
    clr.w   0x129A(%a5)
    clr.w   0x129C(%a5)
    rts

/* d1=word0/attr nibble+flip bits, d2=PC090OJ Y word, d3=source artwork code,
 * d4=PC090OJ X word, native_sprite_lane selects queue.  Preserves all caller
 * registers.  Hidden/blank/code-zero pieces append nothing.  All lanes retain
 * the producer's arcade-semantic Y; the shared visible-origin conversion is
 * applied once when the final SAT entry is encoded. */
native_sprite_emit:
    movem.l %d0-%d7/%a0-%a2, -(%sp)
    btst    #13, %d3                    /* offline-finalized 0x2000|vi; vi zero is valid */
    bne.s   .Lnse_identity_ready
    move.w  %d3, %d0
    andi.w  #0x1FFF, %d0
    beq     .Lnse_done
    cmpi.w  #0x00FF, %d0
    beq     .Lnse_done
.Lnse_identity_ready:
    move.w  %d2, %d0
    andi.w  #0x01FF, %d0
    cmpi.w  #0x0180, %d0
    beq     .Lnse_done

    moveq   #0, %d0
    move.b  native_sprite_lane+1, %d0
    cmpi.w  #NATIVE_LANE_HUD, %d0
    beq.s   .Lnse_hud
    cmpi.w  #NATIVE_LANE_FRONT_EFFECT, %d0
    beq.s   .Lnse_front_effect
    cmpi.w  #NATIVE_LANE_PLAYER_FRONT, %d0
    beq.s   .Lnse_player_front
    cmpi.w  #NATIVE_LANE_MIDDLE, %d0
    beq.s   .Lnse_middle
    cmpi.w  #NATIVE_LANE_PLAYER_BODY, %d0
    beq.s   .Lnse_player_body
    cmpi.w  #NATIVE_LANE_BACK_ENEMY, %d0
    beq.s   .Lnse_back_enemy
    bra     .Lnse_done
.Lnse_hud:
    lea     native_queue_hud, %a0
    lea     native_hud_count, %a1
    move.w  #NATIVE_HUD_BOUND, %d5
    bra.s   .Lnse_store
.Lnse_front_effect:
    lea     native_queue_front_effect, %a0
    lea     native_front_effect_count, %a1
    move.w  #NATIVE_FRONT_EFFECT_BOUND, %d5
    bra.s   .Lnse_store
.Lnse_player_front:
    lea     native_queue_player_front, %a0
    lea     native_player_front_count, %a1
    move.w  #NATIVE_PLAYER_FRONT_BOUND, %d5
    bra.s   .Lnse_store
.Lnse_middle:
    lea     native_queue_middle, %a0
    lea     native_middle_count, %a1
    move.w  #NATIVE_MIDDLE_BOUND, %d5
    bra.s   .Lnse_store
.Lnse_player_body:
    lea     native_queue_player_body, %a0
    lea     native_player_body_count, %a1
    move.w  #NATIVE_PLAYER_BODY_BOUND, %d5
    bra.s   .Lnse_store
.Lnse_back_enemy:
    lea     native_queue_back_enemy, %a0
    lea     native_back_enemy_count, %a1
    move.w  #NATIVE_BACK_ENEMY_BOUND, %d5
.Lnse_store:
    move.w  (%a1), %d0
    cmp.w   %d5, %d0
    bhs.s   .Lnse_done
    move.w  %d0, %d6
    lsl.w   #3, %d6
    adda.w  %d6, %a0
    move.w  %d1, (%a0)+
    move.w  %d2, (%a0)+
    move.w  %d3, (%a0)+
    move.w  %d4, (%a0)+
    addq.w  #1, (%a1)
    .global profile_native_queue_return
profile_native_queue_return:
.Lnse_done:
    movem.l (%sp)+, %d0-%d7/%a0-%a2
    rts

/* Generated-frame fast enqueue.  The Python frame table already owns piece
 * structure, so select the lane once per generated frame rather than saving
 * eleven registers and redispatching the same lane for every piece.  Context:
 * A3=queue base, A6=count word, A2=end; D0/A1 are scratch. */
native_sprite_fast_context:
    moveq   #0, %d0
    move.b  native_sprite_lane+1, %d0
    cmpi.w  #NATIVE_LANE_HUD, %d0
    beq.s   .Lnsfc_hud
    cmpi.w  #NATIVE_LANE_FRONT_EFFECT, %d0
    beq.s   .Lnsfc_front_effect
    cmpi.w  #NATIVE_LANE_PLAYER_FRONT, %d0
    beq.s   .Lnsfc_player_front
    cmpi.w  #NATIVE_LANE_MIDDLE, %d0
    beq.s   .Lnsfc_middle
    cmpi.w  #NATIVE_LANE_PLAYER_BODY, %d0
    beq.s   .Lnsfc_player_body
    lea     native_queue_back_enemy, %a3
    lea     native_back_enemy_count, %a6
    lea     native_queue_back_enemy_end, %a2
    rts
.Lnsfc_hud:
    lea     native_queue_hud, %a3
    lea     native_hud_count, %a6
    lea     native_queue_hud_end, %a2
    rts
.Lnsfc_front_effect:
    lea     native_queue_front_effect, %a3
    lea     native_front_effect_count, %a6
    lea     native_queue_front_effect_end, %a2
    rts
.Lnsfc_player_front:
    lea     native_queue_player_front, %a3
    lea     native_player_front_count, %a6
    lea     native_queue_player_front_end, %a2
    rts
.Lnsfc_middle:
    lea     native_queue_middle, %a3
    lea     native_middle_count, %a6
    lea     native_queue_middle_end, %a2
    rts
.Lnsfc_player_body:
    lea     native_queue_player_body, %a3
    lea     native_player_body_count, %a6
    lea     native_queue_player_body_end, %a2
    rts

native_sprite_emit_fast:
    btst    #13, %d3
    bne.s   .Lnsef_identity_ready
    move.w  %d3, %d0
    andi.w  #0x1FFF, %d0
    beq.s   .Lnsef_done
    cmpi.w  #0x00FF, %d0
    beq.s   .Lnsef_done
.Lnsef_identity_ready:
    move.w  %d2, %d0
    andi.w  #0x01FF, %d0
    cmpi.w  #0x0180, %d0
    beq.s   .Lnsef_done
    moveq   #0, %d0
    move.w  (%a6), %d0
    lsl.w   #3, %d0
    lea     0(%a3,%d0.w), %a1
    cmpa.l  %a2, %a1
    bhs.s   .Lnsef_done
    move.w  %d1, (%a1)+
    move.w  %d2, (%a1)+
    move.w  %d3, (%a1)+
    move.w  %d4, (%a1)+
    addq.w  #1, (%a6)
.Lnsef_done:
    rts

native_stage_dispatch_41dae:
    movem.l %d0-%d7/%a0-%a6, -(%sp)
    /* The sprite-control colbank cannot change inside this private native
     * dispatch: every writer is an arcade-side call-site replacement outside
     * the stage walk.  Normalize its frame-invariant high bits once for all
     * actor probes instead of repeating mask/shift work per active actor. */
    move.w  pc090oj_sprite_ctrl_shadow, %d0
    andi.w  #0x00E0, %d0
    lsr.w   #1, %d0
    move.b  %d0, native_sprite_lane
    move.b  #NATIVE_LANE_PLAYER_FRONT, native_sprite_lane+1
    lea     0x0508(%a5), %a4
    lea     0x00D001C8, %a1
    moveq   #(2 - 1), %d5
.Lns41_players1:
    moveq   #13, %d2
    bsr     .Lnative_emit_actor_common
    adda.w  #64, %a4
    dbra    %d5, .Lns41_players1

    move.b  #NATIVE_LANE_MIDDLE, native_sprite_lane+1
    lea     0x05C8(%a5), %a4
    lea     0x00D00300, %a1
    moveq   #(6 - 1), %d5
.Lns41_middle:
    moveq   #4, %d2
    bsr     .Lnative_emit_actor_common
    adda.w  #64, %a4
    dbra    %d5, .Lns41_middle

    move.b  #NATIVE_LANE_BACK_ENEMY, native_sprite_lane+1
    lea     0x02C8(%a5), %a4
    lea     0x00D00460, %a1
    moveq   #0, %d5
.Lns41_enemy:
    moveq   #10, %d2
    cmpi.w  #8, %d5
    bne.s   .Lns41_enemy_count_ok
    moveq   #19, %d2
.Lns41_enemy_count_ok:
    tst.b   5(%a4)
    beq     .Lnative_actor_advance_only_41_enemy
    /* Arcade 0x41E40 sends mode flag +3 != 0 through the semantic
     * visibility classifier at 0x3EFBE; it does not reject those actors.
     * Reproduce that decision from retained actor state before direct SAT
     * expansion.  In particular, state 0x20 uses the common wrapped-X
     * predicate, which admits the Segment-5 swinging-rope actor. */
    tst.b   3(%a4)
    beq     .Lns41_enemy_emit
    moveq   #0, %d0
    move.b  5(%a4), %d0
    cmpi.b  #0x17, %d0
    beq     .Lns41_enemy_visible_common
    cmpi.b  #0x1A, %d0
    beq     .Lns41_enemy_visible_1a
    cmpi.b  #0x20, %d0
    beq     .Lns41_enemy_visible_common
    cmpi.b  #0x13, %d0
    beq     .Lns41_enemy_visible_13
    cmpi.b  #0x22, %d0
    beq     .Lns41_enemy_visible_22
    cmpi.b  #0x15, %d0
    beq     .Lns41_enemy_visible_15
    bra     .Lns41_enemy_emit

.Lns41_enemy_visible_common:           /* arcade 0x3EFC8 */
    btst    #7, 0x34(%a4)
    bne     .Lns41_enemy_emit
    move.w  0x16(%a4), %d0
    andi.w  #0x01FF, %d0
    cmpi.w  #0x0180, %d0
    blo     .Lns41_enemy_emit
    bra     .Lnative_actor_advance_only_41_enemy

.Lns41_enemy_visible_1a:               /* arcade 0x3EFEC */
    cmpi.w  #0x0087, 0x013E(%a5)
    blo     .Lns41_enemy_visible_1a_low
    cmpi.w  #0xFE08, 0x34(%a4)
    blo     .Lnative_actor_advance_only_41_enemy
    bra     .Lns41_enemy_emit
.Lns41_enemy_visible_1a_low:
    tst.b   0x32(%a4)
    beq     .Lns41_enemy_visible_common
    btst    #7, 0x0742(%a4)
    bne     .Lnative_actor_advance_only_41_enemy
    bra     .Lns41_enemy_emit

.Lns41_enemy_visible_13:               /* arcade 0x3F01E */
    btst    #0, 1(%a4)
    bne     .Lns41_enemy_emit
    btst    #7, 0x34(%a4)
    bne     .Lns41_enemy_emit
    bra     .Lnative_actor_advance_only_41_enemy

.Lns41_enemy_visible_22:               /* arcade 0x3F03C */
    cmpi.b  #0x79, 0x0D(%a4)
    bne     .Lns41_enemy_emit
    cmpi.w  #0x0050, 0x34(%a4)
    blo     .Lns41_enemy_emit
    cmpi.w  #0xFE60, 0x34(%a4)
    bhs     .Lns41_enemy_emit
    bra     .Lnative_actor_advance_only_41_enemy

.Lns41_enemy_visible_15:               /* arcade 0x3F064 */
    cmpi.w  #0x0071, 0x013E(%a5)
    bne     .Lns41_enemy_emit
    btst    #7, 0x16(%a4)
    bne     .Lnative_actor_advance_only_41_enemy

.Lns41_enemy_emit:
    bsr     .Lnative_emit_actor_common
    bra.s   .Lns41_enemy_next
.Lnative_actor_advance_only_41_enemy:
    move.w  %d2, %d0
    lsl.w   #3, %d0
    adda.w  %d0, %a1
.Lns41_enemy_next:
    adda.w  #64, %a4
    addq.w  #1, %d5
    cmpi.w  #9, %d5
    blo     .Lns41_enemy

    move.b  #NATIVE_LANE_FRONT_EFFECT, native_sprite_lane+1
    lea     0x0748(%a5), %a4
    lea     0x00D00170, %a1
    moveq   #(11 - 1), %d5
.Lns41_effect:
    moveq   #1, %d2
    tst.b   0x36(%a4)
    bne.s   .Lnative_actor_advance_only_41_effect
    bsr     .Lnative_emit_actor_common
    bra.s   .Lns41_effect_next
.Lnative_actor_advance_only_41_effect:
    adda.w  #8, %a1
.Lns41_effect_next:
    adda.w  #64, %a4
    dbra    %d5, .Lns41_effect
    movem.l (%sp)+, %d0-%d7/%a0-%a6
    rts

native_stage_dispatch_45dfa:
    movem.l %d0-%d7/%a0-%a6, -(%sp)
    move.w  pc090oj_sprite_ctrl_shadow, %d0
    andi.w  #0x00E0, %d0
    lsr.w   #1, %d0
    move.b  %d0, native_sprite_lane
    move.b  #NATIVE_LANE_BACK_ENEMY, native_sprite_lane+1
    lea     0x05C8(%a5), %a4
    lea     0x00D00460, %a1
    moveq   #(6 - 1), %d5
.Lns45_enemy:
    moveq   #10, %d2
    cmpi.w  #2, 0x0214(%a5)
    bls.s   .Lns45_enemy_count_ok
    moveq   #20, %d2
.Lns45_enemy_count_ok:
    bsr     .Lnative_emit_actor_common
    adda.w  #64, %a4
    dbra    %d5, .Lns45_enemy

    move.b  #NATIVE_LANE_FRONT_EFFECT, native_sprite_lane+1
    lea     0x0748(%a5), %a4
    lea     0x00D00170, %a1
    moveq   #(6 - 1), %d5
.Lns45_effect:
    moveq   #6, %d2
    bsr     .Lnative_emit_actor_common
    adda.w  #64, %a4
    dbra    %d5, .Lns45_effect

    move.b  #NATIVE_LANE_MIDDLE, native_sprite_lane+1
    lea     0x08C8(%a5), %a4
    lea     0x00D00300, %a1
    moveq   #(5 - 1), %d5
.Lns45_middle:
    moveq   #4, %d2
    bsr     .Lnative_emit_actor_common
    adda.w  #64, %a4
    dbra    %d5, .Lns45_middle
    movem.l (%sp)+, %d0-%d7/%a0-%a6
    rts

/* A4=actor, D2=piece budget for this actor.  native_sprite_lane (set by the
 * caller) selects the destination semantic lane.
 *
 * Build 0260: DIRECT-NATIVE gameplay sprite production.  Build 0259's bridge --
 * which ran the relocated arcade record-expander (0x3D254) into an eight-byte
 * PC090OJ-format scratch tuple and decoded it back -- is removed.  This routine
 * reproduces the arcade actor->piece expansion directly from the arcade
 * semantic state and emits each 16x16 piece straight into the native semantic
 * lane, with NO PC090OJ record, NO 0xD00000, NO Y=0x180 park record, NO scratch
 * tuple, and NO pack-then-decode.
 *
 * Provenance (original-arcade MAME attract-demo trace,
 * states/traces/direct_native_sprite_provenance_*): 100% of Stage-1 gameplay
 * actors dispatch to the DEFAULT expander (0x3C950, descriptor type nibble
 * 0x00); zero specialized-type actor-frames were observed.  The default
 * expander's per-piece fields are all live actor/mapping state:
 *   attr@0  = (per-piece type 0x80 ? flipX 0x4000 : 0) | (a4@39 if bit6 set)
 *   Y       = sext(mapY) + a4@26  (+ a4@24 when per-piece type 0x70)
 *   code    = a4@30 + (flip ? -mapCode : mapCode)   [read directly, no record]
 *   X       = sext(mapX) + a4@22   (mirror branch: a4@22 - mapX - 0x10)
 * per-piece mapping stream = [control, Ybyte, codebyte, Xbyte]; control 0xFF is
 * a 1-byte blank/park (emit nothing).  The original 0x3C954/0x3CA26 selector
 * uses raw actor fields a4@0x20 bit 0, a4@0x03, and a4@0x02; the exact general
 * predicate is retained below without assigning unproven semantic names to
 * a4@0x20 or a4@0x03.  a0 = family_descriptor = reloc_table_base +
 * u16[reloc_table_base + class*2]. */
    .global profile_native_actor_entry
profile_native_actor_entry:
.Lnative_emit_actor_common:
    tst.b   0(%a4)                     /* active */
    beq     .Lnea_ret
    tst.w   %d2
    beq     .Lnea_ret
    /* Every caller is inside native_stage_dispatch_41dae/45dfa, whose outer
     * frame already preserves D0-D7/A0-A6 for the retained arcade caller.
     * Across one actor probe only D5 (stage loop/index) and A1 (legacy lane
     * cursor used by skip paths) remain live.  The former nested full saves in
     * this wrapper and both generated probes duplicated that contract once per
     * actor and dominated dense-frame setup cost. */
    movem.l %d5/%a1, -(%sp)

    /* Phase B: exact semantic keys only.  A native hit emits a precompiled
     * general-compositor frame; every unlisted selector returns to the accepted
     * Build-0403 interpreter below without changing retained actor state. */
    bsr     .Lnative_generic_frame_try
    tst.b   %d0
    bne.s   .Lnea_restore
    /* Death presentation has a finite, exhaustively generated domain.  Keep
     * the ordinary Level-B routes first, then probe the compact death stream
     * only for its three exact source-pattern families. */
    cmpi.w  #0x0A73, 0x1E(%a4)
    beq.s   .Lnea_try_death
    cmpi.w  #0x0275, 0x1E(%a4)
    beq.s   .Lnea_try_death
    cmpi.w  #0x0A5A, 0x1E(%a4)
    bne.s   .Lnea_try_universal
.Lnea_try_death:
    bsr     .Lnative_death_frame_try
    tst.b   %d0
    bne.s   .Lnea_restore
.Lnea_try_universal:
    bsr     .Lnative_universal_general_try
    /* Static closure + Build-0406 runtime zero-fallback proof make the old
     * descriptor interpreter unreachable.  A generated miss owns no output;
