.Lnc51_generated_loop:
    moveq   #0, %d0
    btst    #4, 9(%a0)
    bne.s   .Lnc51_generated_need_cond
    btst    #5, 9(%a0)
    beq.s   .Lnc51_generated_accept
    bra.s   .Lnc51_generated_compute_cond
.Lnc51_generated_need_cond:
    moveq   #1, %d0
.Lnc51_generated_compute_cond:
    moveq   #0, %d1
    cmpi.b  #2, 0x0118(%a5)
    beq.s   .Lnc51_generated_cond_ready
    move.w  0x013E(%a5), %d1
    cmpi.w  #0x0062, %d1
    bcs.s   .Lnc51_generated_cond_ready
    cmpi.w  #0x0064, %d1
    bcc.s   .Lnc51_generated_cond_ready
    moveq   #1, %d1
.Lnc51_generated_cond_ready:
    cmp.b   %d0, %d1
    bne.s   .Lnc51_generated_next
.Lnc51_generated_accept:
    move.w  2(%a0), %d2
    add.w   0x1A(%a4), %d2
    btst    #2, 9(%a0)
    beq.s   .Lnc51_generated_y_ready
    add.w   0x18(%a4), %d2
.Lnc51_generated_y_ready:
    move.w  0(%a0), %d3
    add.w   0x16(%a4), %d3
    move.w  %d2, (%a3)+
    move.w  %d3, (%a3)+
    subq.w  #1, %d6
    bmi.s   .Lnc51_generated_done
.Lnc51_generated_next:
    adda.w  #10, %a0
    subq.w  #1, %d7
    bne     .Lnc51_generated_loop
.Lnc51_generated_done:
    movea.l (%sp)+, %a2
    move.w  (%sp)+, %d7
    tst.w   %d6
    bmi     .Lnc51_next_entry
    bra     .Lnc51_fill_remaining
.Lnc51_generated_miss:
    movea.l (%sp)+, %a2
    move.w  (%sp)+, %d7
    /* Same generated closure as the visual consumer.  Retire the old arcade
     * descriptor parser from the live contact path; an impossible miss fills
     * the registration with the established inactive coordinates. */
    bra     .Lnc51_fill_entry

    /* Resolve the same family/animation mapping program as native sprite output. */
    moveq   #0, %d1
    move.b  0x38(%a4), %d1
    cmpi.w  #4, %d1
    bhi     .Lnc51_fill_entry
    lsl.w   #2, %d1
    lea     .Lnea_fam_bases, %a1
    movea.l (%a1,%d1.w), %a1
    moveq   #0, %d0
    move.b  1(%a4), %d0
    add.w   %d0, %d0
    move.w  (%a1,%d0.w), %d0
    lea     (%a1,%d0.w), %a0
    moveq   #8, %d6                 /* first nine arcade object records */

    move.b  (%a0), %d5
    andi.b  #0xF0, %d5
    beq.s   .Lnc51_default
    cmpi.b  #0x40, %d5
    beq.s   .Lnc51_default
    cmpi.b  #0x70, %d5
    beq.s   .Lnc51_default
    cmpi.b  #0x80, %d5
    beq.s   .Lnc51_default
    cmpi.b  #0xD0, %d5
    beq.s   .Lnc51_default
    cmpi.b  #0xE0, %d5
    beq.s   .Lnc51_default
    cmpi.b  #0xF0, %d5
    beq.s   .Lnc51_default
    bra     .Lnc51_special

.Lnc51_default:
    /* Select once per actor through the exact helper used by visual expansion.
     * D4.b = 1 normal X, 0 mirrored/repositioned X. */
    bsr     .Lnative_mapping_branch_is_normal
    move.b  %d0, %d4
.Lnc51_default_loop:
    moveq   #0, %d0
    move.b  (%a0)+, %d0             /* control/type; FF terminates */
    cmpi.b  #0xFF, %d0
    beq     .Lnc51_fill_remaining
    move.b  %d0, %d5
    andi.b  #0xF0, %d5
    moveq   #0, %d2
    move.b  (%a0)+, %d2             /* mapping Y */
    ext.w   %d2
    add.w   0x1A(%a4), %d2
    cmpi.b  #0x70, %d5
    bne.s   .Lnc51_default_y_ok
    tst.b   %d4                       /* arcade applies +0x18 only on normal branch */
    beq.s   .Lnc51_default_y_ok
    add.w   0x18(%a4), %d2
.Lnc51_default_y_ok:
    addq.l  #1, %a0                 /* tile-code byte is not a contact input */
    moveq   #0, %d3
    move.b  (%a0)+, %d3             /* mapping X */
    ext.w   %d3
    tst.b   %d4
    bne.s   .Lnc51_default_right
    neg.w   %d3
    subi.w  #0x0010, %d3
.Lnc51_default_right:
    add.w   0x16(%a4), %d3
    move.w  %d2, (%a3)+
    move.w  %d3, (%a3)+
    dbra    %d6, .Lnc51_default_loop
    bra.s   .Lnc51_next_entry

.Lnc51_special:
    movea.l 2(%a0), %a0
    moveq   #0, %d0
    move.b  0x0B(%a4), %d0
    move.w  %d0, %d1
    add.w   %d0, %d0
    add.w   %d1, %d0               /* frame * 3 */
    adda.w  %d0, %a0
.Lnc51_special_loop:
    moveq   #0, %d2
    move.b  (%a0)+, %d2
    cmpi.b  #0xFF, %d2
    beq.s   .Lnc51_fill_remaining
    ext.w   %d2
    add.w   0x1A(%a4), %d2
    move.w  0x16(%a4), %d3
    move.w  %d2, (%a3)+
    move.w  %d3, (%a3)+
    dbra    %d6, .Lnc51_special_loop
    bra.s   .Lnc51_next_entry

.Lnc51_fill_entry:
    moveq   #8, %d6
.Lnc51_fill_remaining:
    move.w  #0x01FF, (%a3)+
    move.w  #0x01FF, (%a3)+
    dbra    %d6, .Lnc51_fill_remaining
    .global profile_native_contact_record_done
profile_native_contact_record_done:
.Lnc51_next_entry:
    addq.l  #6, %a2
    dbra    %d7, .Lnc51_entry
    movem.l (%sp)+, %d0-%d7/%a0-%a4
    .global profile_native_contact_return
profile_native_contact_return:
    rts



/* RETIRED (setup/priority PC090OJ family).  This helper only PARKED/cleared
 * object-RAM records 9..16 (its retired PLAYER_FRONT a5+0x170 tuple rebuild was
 * already absent; PLAYER_FRONT is main-loop native staging).  Verified no live
 * producer writes records 9..16 with content, so the clear services nothing
 * (records stay boot-blank).  Retired to a no-op (preserves all registers). */
genesistan_pc090oj_hook_target_59f5e:
    rts

/* PC090OJ ctrl register (word offset 0x0DFF / HW 0x00D01BFE).
 * Bit 0 is the global-flip control (a change flips every sprite on/off screen),
 * so an actual change reevaluates all 256 records by requesting a full
 * candidate sweep processed at the next VBlank (§9-E.4).
 */
genesistan_pc090oj_ctrl_set_1:
    cmpi.w  #1, pc090oj_ctrl_shadow
    beq.s   .Lctrl_set_1_done
    move.w  #1, pc090oj_ctrl_shadow
.Lctrl_set_1_done:
    rts

genesistan_pc090oj_ctrl_set_0:
    tst.w   pc090oj_ctrl_shadow
    beq.s   .Lctrl_set_0_done
    clr.w   pc090oj_ctrl_shadow
.Lctrl_set_0_done:
    rts

/* External sprite_ctrl at HW 0x00380000.  D0 holds the arcade value; its colour
 * bank feeds sprite palette selection.  On an actual change, reevaluate (a full
 * sweep is a safe superset of the represented-only palette refresh).
 */
genesistan_pc090oj_sprite_ctrl_write_d0:
    cmp.w   pc090oj_sprite_ctrl_shadow, %d0
    beq.s   .Lsprite_ctrl_write_done
    move.w  %d0, pc090oj_sprite_ctrl_shadow
.Lsprite_ctrl_write_done:
    rts

genesistan_pc090oj_sprite_ctrl_clear:
    tst.w   pc090oj_sprite_ctrl_shadow
    beq.s   .Lsprite_ctrl_clear_done
    clr.w   pc090oj_sprite_ctrl_shadow
.Lsprite_ctrl_clear_done:
    rts

genesistan_hook_3ad44_dispatch:
    movem.l %d0-%d7/%a0-%a6, -(%sp)

    /* A0 dispatch: PC080SN C-range ONLY -> [0x00C00000,0x00C10000).
     * The PC090OJ D-range (0x00D00000..0x00D007FF) is fully retired: its only
     * callers were the arcade object-RAM clear routines 0x03AD4C / 0x03AD72,
     * which are now RTS (their whole body was obsolete PC090OJ record clearing
     * with no native effect), so no D-range address ever reaches this
     * dispatcher.  No PC090OJ recognition remains here.  This dispatcher now
     * survives ONLY for its still-live PC080SN C-range callers (0x03AE70/80,
     * 0x03AF38/48) and is scheduled for deletion once PC080SN C-range ownership
     * is native (see the PC080SN Final-Retirement Handoff). */
    move.l  %a0, %d2
    cmpi.l  #0x00C00000, %d2
    blo     .Lhook_3ad44_audit
    cmpi.l  #0x00C10000, %d2
    bhs     .Lhook_3ad44_audit

.Lhook_3ad44_tilemap:
    cmpi.l  #0x00C04000, %d2
    blo.s   .Lhook_3ad44_bg_names
    cmpi.l  #0x00C08000, %d2
    blo.s   .Lhook_3ad44_bg_scroll
    cmpi.l  #0x00C0C000, %d2
    blo.s   .Lhook_3ad44_fg_names
    bsr     genesistan_hook_pc080sn_fg_scroll_fill
    bra     .Lhook_3ad44_finish

.Lhook_3ad44_bg_names:
    bsr     genesistan_hook_tilemap_bg_fill
    bra     .Lhook_3ad44_finish

.Lhook_3ad44_bg_scroll:
    bsr     genesistan_hook_pc080sn_bg_scroll_fill
    bra     .Lhook_3ad44_finish

.Lhook_3ad44_fg_names:
    bsr     genesistan_hook_tilemap_fg_fill
    bra     .Lhook_3ad44_finish

.Lhook_3ad44_audit:
    /* Reuse §7.3 audit-guard capture + heartbeat halt loop. */
    move.l  60(%sp), %d0
    move.l  %d0, audit_guard_caller_pc

    lea     audit_guard_register_snapshot, %a1
    moveq   #(15 - 1), %d0
.Lhook_3ad44_snap:
    move.l  (%sp,%d0.w*4), %d1
    move.l  %d1, (%a1)+
    dbra    %d0, .Lhook_3ad44_snap

    move.w  0x00C00008, audit_guard_vcount
    move.w  #0x3AD4, audit_guard_fired_flag
    bra     .Lag_halt_loop

.Lhook_3ad44_finish:
    movem.l (%sp)+, %d0-%d7/%a0-%a6
    rts

/* RETIRED (setup/priority PC090OJ family).  This helper only initialized
 * object-RAM records 76..79 with code=0 (blank / not-drawable) at off-screen
 * X=0x160: zero visible semantic output.  The former priority/flip "ladder"
 * intent is already owned by the native lane ORDER (gameplay emits lanes in
 * priority order); no ordering is lost.  Verified no producer writes records
 * 76..79 with nonzero code, so they stay boot-blank without this emit.  Retired
 * to a no-op (preserves all registers). */
genesistan_pc090oj_hook_init_priority_3ad84:
    rts

genesistan_pc090oj_hook_score_digit_3b802:
    /* Build 0270: RETIRED.  All 0x3B802 consumers are now produced natively by
     * the native_frontend_hud_emit subsystem (Build 0272): player/high scores +
     * credit-line digits for the title and every other frontend scene, and the
     * gameplay project_p1_hud path.  That subsystem also retires the stale
     * PC090OJ digit records (code-gated), so the frontend scanner no longer
     * carries any record-number HUD skip.  Every live consumer has a native
     * owner (consumer coverage matrix in the build report). */
    rts

/* RETIRED (setup/priority PC090OJ family).  This helper only initialized
 * object-RAM records 72..75 with code=0 (blank / not-drawable): zero visible
 * semantic output, and PLAYER_BODY is main-loop native staging.  Verified no
 * producer writes records 72..75 with nonzero code, so the records stay
 * boot-blank without this emit.  Retired to a no-op (preserves all registers).
 * See docs/design/Andy_5a502_ownership_setup_priority_native_conversion.md. */
genesistan_pc090oj_hook_slot_init_54052:
    rts

/* arcade_pc 0x054810: final native realization of the player-attached
 * damage/impact auxiliary selected by the retained 0x0547C0 state machine.
 * a0 points at the selected four-piece source frame.  Historical PC090OJ
 * records 44..47 and their hardware-slot identity are deliberately absent. */
genesistan_pc090oj_hook_player_aux_native_54810:
    movem.l %d0-%d7/%a0-%a6, -(%sp)

    move.b  #NATIVE_LANE_FRONT_EFFECT, native_sprite_lane+1
    moveq   #4, %d7
.Lplayer_aux_native_loop:
    move.w  4(%a0), %d1

    moveq   #0, %d2
    move.b  3(%a0), %d2
    ext.w   %d2
    add.w   0x129C(%a5), %d2
    addq.w  #1, %d2
    andi.w  #0x01FF, %d2

    move.w  (%a0), %d3

    moveq   #0, %d4
    move.b  2(%a0), %d4
    ext.w   %d4
    add.w   0x129A(%a5), %d4
    andi.w  #0x01FF, %d4

    bsr     native_sprite_emit

    adda.w  #6, %a0
    subq.w  #1, %d7
    bne.s   .Lplayer_aux_native_loop

    movem.l (%sp)+, %d0-%d7/%a0-%a6
    rts

/* Native item-screen tick. The arcade cadence and A5+0x10EE remain the sole
 * scroll authority. Only an 8-pixel boundary asks the Plane-B ring to replace
 * one pre-baked row. */
genesistan_pc090oj_hook_sprite_decay_5607c:
    move.w  0x1392(%a5), %d0
    andi.w  #0x0003, %d0
    bne.s   .Lhook_5607c_done

    clr.w   0x10AE(%a5)
    clr.w   0x10B0(%a5)

    move.w  0x10EE(%a5), %d1
    subq.w  #1, %d1
    andi.w  #0x01FF, %d1
    move.w  %d1, 0x10EE(%a5)
    move.w  %d1, staged_scroll_y_bg
    move.w  0x10EC(%a5), staged_scroll_x_bg
    move.w  0x10B0(%a5), staged_scroll_y_fg
    move.w  0x10AE(%a5), staged_scroll_x_fg
    andi.w  #0x0007, %d1
    bne.s   .Lhook_5607c_done
    bsr     genesistan_item_ring_advance

.Lhook_5607c_done:
    rts

/* Compatibility entry for the now-retired PC090OJ copy sites. The native item
 * entry owns generated templates; no ROM tuple pointer or second scroll state. */
genesistan_pc090oj_hook_copy_56114:
    move.w  #1, transient_items_active
    rts

/* Frontend-direct retirement (was: park the item object-RAM records).  The
 * arcade clear is the semantic end-of-life for the transient item family and
 * the presentation handoff into READY, so retire native item state and restore
 * frontend-owned patterns/palettes/SAT before the retained plane producers run.
 *
 * Original arcade 0x056440 finishes by calling the general tilemap-clear
 * routine at arcade_pc 0x0561A0.  Replacing the whole 0x056440 body made that
 * internal call unreachable, so preserve its semantic consequences explicitly:
 * reset retained/native scroll ownership, clear both final Genesis-format
 * staged name tables, and mark their rows dirty. This is the original generic
 * clear contract, not a ROUND/READY or scene gate. */
genesistan_pc090oj_hook_zero_fill_56440:
    clr.w   transient_items_active

    /* RG-003: 0x056440 is also the retained death/item-to-READY lifecycle
     * boundary.  Restore the frontend pattern/palette owner and stage a clean
     * native SAT before the retained READY producer repopulates the planes. */
    bsr     genesistan_frontend_owner_reset

    /* Build 0458 / OPEN-031: the original 0x056440 teardown called the generic
     * 0x0561A0 clear, whose semantic prologue zeroed all four retained PC080SN
     * scroll words and published them before clearing the two name tables.
     * Replacing the whole caller in Build 0453 accidentally preserved only the
     * table clear.  The scrolling item screen consequently handed its rotated
     * A5+0x10EE / native VSRAM phase to the fresh R1 Segment-0 fill.  Restore
     * that omitted one-shot scroll handoff here. */
    clr.w   0x10AE(%a5)
    clr.w   0x10B0(%a5)
    clr.w   0x10EC(%a5)
    clr.w   0x10EE(%a5)
    clr.w   staged_scroll_x_fg
    clr.w   staged_scroll_y_fg
    clr.w   staged_scroll_x_bg
    clr.w   staged_scroll_y_bg
    bsr     genesistan_hook_cwindow_clear
    rts

    /* native_queue_hud entry 2, code word: 2 * 8-byte entry + 4.  Keep the
     * displacement as an absolute assembler symbol: spelling the arithmetic
     * expression directly before "(%a0)" selects indexed/full-extension
     * syntax in GNU as instead of the required 68000 d16(A0) mode. */
    .equ NATIVE_HUD_LOW_ENERGY_CODE_OFFSET, 0x0014

genesistan_pc090oj_hook_status_sprite_5a098:
    /* Direct-native gameplay energy/status producer.  Preserve the original
     * arcade semantic state machine and publish its eight ordered visible-piece
     * positions directly into the native HUD lane.  The old PC090OJ destination
     * (HW 0xD00048), eight-byte records, virtual records 30..43 and
     * .Lpc090oj_emit_slot are not part of this path.  The queue is persistent:
     * original 0x5100A can skip this producer, and the arcade records likewise
     * retained their previous semantic output on those frames. */
    movem.l %d0-%d7/%a0-%a6, -(%sp)
    move.w  #8, native_hud_count

    move.w  0x013A(%a5), %d0             /* current energy, high byte = units */
    btst    #15, %d0
    beq.s   .Lstatus_energy_valid
    clr.w   0x013A(%a5)                   /* original invalid-energy recovery */
.Lstatus_energy_valid:
    move.w  #0x00E8, %d2                 /* semantic PC090OJ Y */
    move.w  #0x0010, %d4                 /* first semantic X */

    /* Preserve the original animated leading status piece decision. */
    move.w  0x013A(%a5), %d0
    lsr.w   #8, %d0
    lsr.w   #3, %d0
    andi.w  #0x0007, %d0
    ori.w   #0x0008, %d0
    move.w  %d0, 0x12A6(%a5)
    addi.w  #0x0010, 0x12A4(%a5)
    move.w  0x12A4(%a5), %d1
    move.w  0x12A6(%a5), %d5
    move.w  0x1306(%a5), %d6
    cmpi.w  #0x000C, %d5
    ble.s   .Lstatus_selector_clamped
    moveq   #0x0C, %d5
.Lstatus_selector_clamped:
    subq.w  #2, %d5
    btst    #0, %d6
    bne.s   .Lstatus_selector_odd
    btst    %d5, %d1
    bne.s   .Lstatus_indicator_done
    bra.s   .Lstatus_indicator_update
.Lstatus_selector_odd:
    btst    %d5, %d1
    beq.s   .Lstatus_indicator_done
.Lstatus_indicator_update:
    move.w  0x130A(%a5), %d7
    addi.w  #0x0010, 0x130A(%a5)
    moveq   #7, %d0
    cmpi.w  #7, %d5
    bge.s   .Lstatus_indicator_bit_ready
    subq.w  #1, %d0
.Lstatus_indicator_bit_ready:
    move.w  #0x03CA, %d3
    btst    %d0, %d7
    beq.s   .Lstatus_indicator_code_ready
    addq.w  #1, %d3
.Lstatus_indicator_code_ready:
    btst    %d0, %d7
    bne.s   .Lstatus_indicator_counter_done
    addq.w  #1, 0x1306(%a5)
.Lstatus_indicator_counter_done:
    moveq   #0, %d1                     /* original word0: no local flip/bank */
    moveq   #0, %d0                     /* semantic output index 0 */
    bsr     .Lstatus_store_piece
.Lstatus_indicator_done:
    addi.w  #0x0010, %d4

    /* 0x12FC==1 is the arcade refresh gate.  Otherwise retain the last native
     * semantic bar, exactly as the original records remained untouched. */
    cmpi.w  #1, 0x12FC(%a5)
    bne     .Lstatus_low_energy_blink

    moveq   #0, %d1
    move.w  #0x03CC, %d3                 /* left cap */
    moveq   #1, %d0
    bsr     .Lstatus_store_piece
    addi.w  #0x0010, %d4

    move.w  0x013A(%a5), %d0
    lsr.w   #8, %d0
    cmpi.w  #0x0030, %d0
    blo.s   .Lstatus_energy_clamped
    move.w  #0x0030, %d0
.Lstatus_energy_clamped:
    move.w  %d0, %d1
    andi.w  #0xFFF8, %d0
    lsr.w   #3, %d0                     /* d0 = full cells (0..6) */
    andi.w  #0x0007, %d1                /* d1 = partial-cell units */
    move.w  %d0, %d5
    moveq   #6, %d6                     /* six semantic energy cells */
    moveq   #2, %d7                     /* first cell output index */
    move.w  %d1, -(%sp)                 /* preserve partial units across emits */
    move.w  #0x00FF, 0x1328(%a5)
    tst.w   %d5
    bne.s   .Lstatus_full_loop_test
    move.w  #1, 0x1328(%a5)

.Lstatus_full_loop_test:
    tst.w   %d5
    beq.s   .Lstatus_partial
.Lstatus_full_loop:
    move.w  #0x03CD, %d3
    move.w  %d7, %d0
    moveq   #0, %d1
    bsr     .Lstatus_store_piece
    addi.w  #0x0010, %d4
    addq.w  #1, %d7
    subq.w  #1, %d6
    subq.w  #1, %d5
    bne.s   .Lstatus_full_loop

.Lstatus_partial:
    move.w  (%sp)+, %d1
    tst.w   %d1
    beq.s   .Lstatus_no_partial
    add.w   %d1, %d1
    lea     .Lstatus_partial_codes, %a1
    move.w  0(%a1,%d1.w), %d3
    move.w  %d3, 0x132A(%a5)
    move.w  %d7, %d0
    moveq   #0, %d1
    bsr     .Lstatus_store_piece
    addi.w  #0x0010, %d4
    addq.w  #1, %d7
    subq.w  #1, %d6
    bra.s   .Lstatus_empty_test
.Lstatus_no_partial:
    move.w  #0x03D5, 0x132A(%a5)

.Lstatus_empty_test:
    tst.w   %d6
    beq.s   .Lstatus_low_energy_blink
.Lstatus_empty_loop:
    move.w  #0x03D5, %d3
    move.w  %d7, %d0
    moveq   #0, %d1
    bsr     .Lstatus_store_piece
    addi.w  #0x0010, %d4
    addq.w  #1, %d7
    subq.w  #1, %d6
    bne.s   .Lstatus_empty_loop

.Lstatus_low_energy_blink:
    cmpi.w  #1, 0x1328(%a5)
    bne.s   .Lstatus_update_lifecycle
    move.w  0x1308(%a5), %d0
    lsr.w   #1, %d0
    btst    #0, %d0
    beq.s   .Lstatus_blink_empty
    move.w  0x132A(%a5), %d0
    bra.s   .Lstatus_blink_store
.Lstatus_blink_empty:
    move.w  #0x03D5, %d0
.Lstatus_blink_store:
    lea     native_queue_hud, %a0
    move.w  %d0, NATIVE_HUD_LOW_ENERGY_CODE_OFFSET(%a0)

.Lstatus_update_lifecycle:
    /* Inline original helper 0x5A244: publish low/normal-energy transitions. */
    cmpi.w  #1, 0x1328(%a5)
    bne.s   .Lstatus_lifecycle_normal
    cmpi.w  #0x00FF, 0x13CE(%a5)
    beq.s   .Lstatus_lifecycle_low_steady
    move.w  #1, 0x13D2(%a5)
    bra.s   .Lstatus_lifecycle_low_commit
.Lstatus_lifecycle_low_steady:
    move.w  #0x0011, 0x13D2(%a5)
.Lstatus_lifecycle_low_commit:
    move.w  #1, 0x13CE(%a5)
    bra.s   .Lstatus_sound
.Lstatus_lifecycle_normal:
    cmpi.w  #1, 0x13CE(%a5)
    beq.s   .Lstatus_lifecycle_normal_steady
    move.w  #0x00FF, 0x13D2(%a5)
    bra.s   .Lstatus_lifecycle_normal_commit
.Lstatus_lifecycle_normal_steady:
    move.w  #0x00FE, 0x13D2(%a5)
.Lstatus_lifecycle_normal_commit:
    move.w  #0x00FF, 0x13CE(%a5)

.Lstatus_sound:
    cmpi.w  #0, 0x12F4(%a5)
    bne.s   .Lstatus_sound_recovery
    cmpi.w  #0x0011, 0x13D2(%a5)
    bne.s   .Lstatus_sound_recovery
    moveq   #6, %d0
    jsr     (0x0003A2EC).l               /* address_map: arcade_pc 0x03A0EC */
    bra.s   .Lstatus_done
.Lstatus_sound_recovery:
    cmpi.w  #0x00FE, 0x13D2(%a5)
    bne.s   .Lstatus_done
    move.w  #0x0029, %d0
    jsr     (0x0003A316).l               /* address_map: arcade_pc 0x03A116 */

.Lstatus_done:
    movem.l (%sp)+, %d0-%d7/%a0-%a6
    rts

/* d0=native semantic output index, d1=attr, d2=Y, d3=code, d4=X.  This is the
 * final native queue shape consumed directly by .Lnq_emit_lane, not a PC090OJ
 * record and not input to any compatibility scanner or decoder. */
.Lstatus_store_piece:
    movem.l %d0/%a0, -(%sp)
    lsl.w   #3, %d0
    lea     native_queue_hud, %a0
    adda.w  %d0, %a0
    move.w  %d1, (%a0)+
    move.w  %d2, (%a0)+
    move.w  %d3, (%a0)+
    move.w  %d4, (%a0)+
    movem.l (%sp)+, %d0/%a0
    rts

.Lstatus_partial_codes:
    .word 0x03D5, 0x03D4, 0x03D3, 0x03D2
    .word 0x03D1, 0x03D0, 0x03CF, 0x03CE

genesistan_pc090oj_hook_audit_guard:
    movem.l %d0-%d7/%a0-%a6, -(%sp)

    /* return address for invoking site */
    move.l  60(%sp), %d0
    move.l  %d0, audit_guard_caller_pc

    /* snapshot registers (d0-d7,a0-a6 = 15 longs) */
    lea     audit_guard_register_snapshot, %a1
    moveq   #(15 - 1), %d0
.Lag_snap:
    move.l  (%sp,%d0.w*4), %d1
    move.l  %d1, (%a1)+
    dbra    %d0, .Lag_snap

    move.w  0x00C00008, audit_guard_vcount
    move.w  #0x510E, audit_guard_fired_flag

.Lag_halt_loop:
    move.b  audit_guard_heartbeat, %d0
    addq.b  #1, %d0
    move.b  %d0, audit_guard_heartbeat
    bra     .Lag_halt_loop

/* ------------------------------------------------------------------------- */
/* VBlank sprite prepare / commit split                                      */

/* ========================================================================= */
/* N1 native sprite pipeline (Build 0219): object table -> shadow SAT.       */
/*                                                                           */
/* The 256-row object table (pc090oj_object_ram) is the arcade program's own */
/* persistent slot-addressed sprite store: incremental producers (score,     */
/* status, decay, copy hooks) update rows in place exactly as arcade code    */
/* updated PC090OJ RAM.  Once per frame ONE ascending pass emits final       */
/* Genesis SAT entries into a double-buffered shadow SAT.  Ascending row     */
/* order = PC090OJ paint priority (MAME pc090oj draws descending, so record  */
/* 0 lands on top; Genesis link order gives the same result).  Retirement is */
/* implicit: rows the producers cleared/blanked simply emit nothing.         */
/* No mirror shadow, no candidates, no representation/eviction engine, no   */
/* record->slot map, no VBlank record scans in gameplay (the pass runs at    */
/* the end of the arcade's own sprite dispatcher; frontend scenes fall back  */
/* to a VBlank pass). Residency is code-keyed and fully associative over the */
/* 49 physical cells left by fixed Plane B + worst-record Plane A.           */
/* ========================================================================= */
    .equ NATIVE_SAT_MAX, 80
    .equ NATIVE_CELLS, 49
    /* Exact two-level reverse index for the Build-0356 residency identity.
     * The forward key is low 12-bit graphics code plus the semantic-profile tag in
     * bit 15.  Normalize that tag to bit 12 for a dense 13-bit key, then use
     * its high nine bits as a 512-entry directory and low nibble within one
     * of at most 49 live 16-byte pages.  Directory/page entries use 0xFF as
     * NOT_RESIDENT; resident leaves store the forward-table byte offset
     * (0,2,...,96), ready for the unchanged SAT hit path. */
    .equ NATIVE_REVERSE_DIRECTORY_BYTES, 512
    .equ NATIVE_REVERSE_PAGE_BYTES, 16
    .equ NATIVE_REVERSE_PAGE_COUNT, NATIVE_CELLS
    .if (SPRITE_TILE_BASE + NATIVE_CELLS * 4) > 1536
    .error "native sprite VRAM ownership exceeds physical pattern slots"
    .endif
    .equ NATIVE_QUEUE_ENTRY_BYTES, 8
    .equ NATIVE_LANE_HUD, 0
    .equ NATIVE_LANE_FRONT_EFFECT, 1
    .equ NATIVE_LANE_PLAYER_FRONT, 2
    .equ NATIVE_LANE_MIDDLE, 3
    .equ NATIVE_LANE_PLAYER_BODY, 4
    .equ NATIVE_LANE_BACK_ENEMY, 5
    .equ NATIVE_HUD_BOUND, 9
    .equ NATIVE_FRONT_EFFECT_BOUND, 36
    .equ NATIVE_PLAYER_FRONT_BOUND, 30
    .equ NATIVE_MIDDLE_BOUND, 24
    .equ NATIVE_PLAYER_BODY_BOUND, 20
    .equ NATIVE_BACK_ENEMY_BOUND, 99

/* Scene selection is rare; the emitted-piece hot path indexes this row directly. */
pc090oj_select_palette_map:
    moveq   #0, %d0
    move.b  genesistan_current_scene_id, %d0
    andi.w  #PALSEL_LUT_SCENE_MASK, %d0
    lsl.w   #PALSEL_LUT_BANK_SHIFT, %d0
    lea     pc090oj_palsel_lut, %a0
    adda.w  %d0, %a0
    move.l  %a0, current_sprite_palette_map
    rts

/* Initialize the exact graphics-key -> resident-slot reverse index.  Called
 * once after bootstrap clears the forward table.  Each of the 49 possible
 * live high-key groups owns a page only while at least one resident key uses
 * it, so 49 pages are sufficient for the 49 forward slots. */
pc090oj_reverse_index_init:
    movem.l %d0-%d1/%d7/%a0, -(%sp)
    moveq   #-1, %d0
    lea     sprite_tile_reverse_directory, %a0
    move.w  #((NATIVE_REVERSE_DIRECTORY_BYTES + NATIVE_REVERSE_PAGE_BYTES * NATIVE_REVERSE_PAGE_COUNT) / 4 - 1), %d7
.Lreverse_init_invalid:
    move.l  %d0, (%a0)+
    dbra    %d7, .Lreverse_init_invalid

    lea     sprite_tile_reverse_page_refcount, %a0
    moveq   #0, %d0
    moveq   #(NATIVE_REVERSE_PAGE_COUNT - 1), %d7
.Lreverse_init_refcounts:
    move.b  %d0, (%a0)+
    dbra    %d7, .Lreverse_init_refcounts

    lea     sprite_tile_reverse_free_pages, %a0
    moveq   #0, %d0
    moveq   #(NATIVE_REVERSE_PAGE_COUNT - 1), %d7
.Lreverse_init_free_pages:
    move.b  %d0, (%a0)+
    addq.b  #1, %d0
    dbra    %d7, .Lreverse_init_free_pages
    move.w  #NATIVE_REVERSE_PAGE_COUNT, sprite_tile_reverse_free_count
    movem.l (%sp)+, %d0-%d1/%d7/%a0
    rts

/* PC090OJ final teardown: .Lpc090oj_mode2_project_p1_hud REMOVED.  It projected the
 * P1 score into object-RAM records 0..8 for a gameplay object-scan path that is no
 * longer reachable (gameplay uses .Lnq_gameplay / .Lnq_project_p1_hud natively). */


/* Build 0250 native semantic-lane finalizer.  Non-gameplay falls back to the
 * legacy object-table scanner; gameplay consumes only the native queues. */
    .global profile_native_finalizer_entry
profile_native_finalizer_entry:
pc090oj_native_emit_pass:
    /* Emit-time palette/variant selection uses the same sprite-control value
     * for every piece in this uninterrupted pass.  Cache the normalized high
     * bits once; direct frontend and gameplay emitters then share the exact
     * same general effective-bank contract. */
    move.w  pc090oj_sprite_ctrl_shadow, %d0
    andi.w  #0x00E0, %d0
    lsr.w   #1, %d0
    move.b  %d0, native_sprite_lane
    move.b  genesistan_current_scene_id, %d0
    cmpi.b  #PC090OJ_SCENE_GAMEPLAY_ID, %d0
    beq     .Lnq_gameplay
    bra     .Lnq_frontend_native
/* Build 0443: title-screen sprites produced by change-driven direct-native producers.
 * Fixed text is a semantic glyph sequence (.Lnq_title_labels: {Y,X,glyph}); the
 * score and high-score digits are generated from the live arcade
 * BCD values (player 0x00FF011E, high score 0x00FF0142) -- no captured digit
 * constants.  Every piece is emitted straight into staged_sprite_sat through
 * the residency + SAT builder the gameplay lanes use: no pc090oj_object_ram,
 * no 0xD00000, no Y=0x180 park, no object-RAM scan.  Scene 0 title-active never
 * reaches the general frontend producer.  Build 0443's seven-byte semantic
 * cache suppresses this entire pass on stable title frames; other frontend
 * screens retain their existing per-frame native path. */
.Lnq_title:
    /* The title's fixed SAT, sprite patterns and digit records are generated
     * offline and installed by genesistan_title_present_once.  Its VBlank
     * service updates only changed digit records, so the generic residency /
     * full-SAT builder has no title-active work. */
    rts

/* Generated final-format icon templates own geometry, pattern slots, palette
 * and order. Runtime derives only visibility/Y from live A5+0x10EE. */
.Lnq_transient_items_emit:
    tst.w   transient_items_active
    beq     .Lti_done
    bsr     genesistan_item_emit_native
.Lti_done:
    rts

/* Direct-native replacement of the retired arcade producer 0x5A502 (the
 * no-human attract/demo eight-glyph GAME OVER row -- NOT the human terminal
 * GAME OVER screen, which is a separate 0x03A420 (2,4,5/6) path).  Invoked from
 * the GAMEPLAY native finalizer under the exact original semantic ownership of
 * the 0x05104E caller (Cody_frontend_gameover_highscore_semantic_model.md): the
 * game-flow state tuple must be active no-human attract gameplay, and the
 * gameplay blink phase must be visible.  This corrects the Build0286 defect
 * where the broad .Lnq_frontend_object_scan ownership let the row appear on the
 * HIGH SCORE TABLE (which also has a5+0x34==0 and can observe bit5 clear).
 * a5 = 0xFF0000; the check reads absolute WRAM (a5 is reused below as the label
 * walker, so it is saved/restored).  Records nothing to object RAM; no Y=0x180
 * park (hidden => emit nothing). */
.Lnq_gameover_emit:
    cmpi.w  #2, 0x00FF0000           /* a5+0x00: gameplay/session umbrella */
    bne     .Lgo_ret
    cmpi.w  #3, 0x00FF0002           /* a5+0x02: active/attract-demo gameplay */
    bne     .Lgo_ret
    move.w  0x00FF0004, %d0          /* a5+0x04: nested state 0 or 1 */
    cmpi.w  #1, %d0
    bhi     .Lgo_ret
    tst.w   0x00FF0034               /* a5+0x34: 0 = no-human/attract session */
    bne     .Lgo_ret
    move.w  0x00FF0200, %d0          /* a5+0x200: gameplay frame/phase tick */
    btst    #5, %d0
    bne     .Lgo_ret                 /* bit5 set => hidden phase */
    move.l  %a5, -(%sp)
    lea     .Lnq_gameover_labels, %a5
.Lgo_loop:
    move.w  (%a5), %d4               /* X, or 0xFFFF terminator */
    cmpi.w  #0xFFFF, %d4
    beq.s   .Lgo_pop
    move.w  2(%a5), %d3              /* glyph code */
    ori.w   #0x8000, %d3             /* current Test object index_map asset */
    move.w  #0x0070, %d2             /* Y = visible */
    moveq   #PC090OJ_GAMEOVER_PROFILE_LINE, %d1
    bsr     .Lnq_emit_entry_cached
    addq.l  #4, %a5
    bra.s   .Lgo_loop
.Lgo_pop:
    move.l  (%sp)+, %a5
.Lgo_ret:
    rts

/* GAME OVER fixed glyph layout: {X, code}.  Codes 0x37,0x38,0x3F,0x40..0x44 =
 * G,A,M,E,O,V,E,R; X 0x60..0x90 then a +0x20 gap then 0xB0..0xE0 -- the exact
 * positions the arcade producer packed into records 83..90. */
.Lnq_gameover_labels:
    .word 0x0060, 0x0037            /* G */
    .word 0x0070, 0x0038            /* A */
    .word 0x0080, 0x003F            /* M */
    .word 0x0090, 0x0040            /* E */
    .word 0x00B0, 0x0041            /* O */
    .word 0x00C0, 0x0042            /* V */
    .word 0x00D0, 0x0043            /* E */
    .word 0x00E0, 0x0044            /* R */
    .word 0xFFFF

/* Build 0450: superseded source retained under an assembly-false guard only
 * for local provenance.  It emits no code and owns no runtime consumer; the
 * generated shared HUD module is the sole frontend HUD owner. */
.if 0
/* -------------------------------------------------------------------------
 * native_frontend_hud_emit -- the complete native frontend HUD subsystem.
 *
 * Single semantic owner of the ENTIRE frontend HUD: player + high-score digits,
 * the credit count, AND the fixed HUD text/labels (HIGH SCORE / 1P / 2UP row,
 * etc.).  Invoked at the frontend boundary -- from .Lnq_title for the
 * title-active state and from the top of .Lnq_frontend_object_scan for every
 * other frontend scene.  Every element is generated directly from live
 * semantic state (BCD 0x00FF011E/0x00FF0142, credit 0x00FF0117) or fixed
 * layout (.Lnq_title_labels) straight into the native SAT via .Lnq_emit_entry.
 *
 * Build 0273: this replaces the arcade PC090OJ HUD producer at the arcade-code
 * boundary.  The arcade builder 0x3B8B0 (records 4..45, via the generic 0x3B930
 * copier) is retired to `rts` (opcode_replace), and the arcade credit builder
 * 0x3B902 (records 17..21) is retired to `rts` in its hook -- so no arcade
 * PC090OJ HUD record is produced at all, the object-RAM scanner renders none of
 * this family, and the Build-0272 write-then-clear workaround is deleted.  The
 * generic 0x3B930 copier is preserved untouched.  Because .Lnq_emit_entry
 * applies the IDENTICAL coordinate transform as .Lpc090oj_decode_record, the
 * native labels reproduce the former scan output exactly. */
native_frontend_hud_emit:
.if RASTAN_DIAG_SCORE_METRIC
    /* Build 0338: overwrite the P1 score with the diagnostic metric BCD right before the frontend HUD
     * reads it, so the metric wins over the arcade score update.  Memory-to-memory, no registers. */
    move.b  diag_score_bcd, 0x00FF011E
    move.b  diag_score_bcd+1, 0x00FF011F
    move.b  diag_score_bcd+2, 0x00FF0120
.endif
    bsr     .Lnq_title_emit_scores       /* live scores + credit -> native SAT */
    bsr     .Lnq_title_emit_labels       /* fixed HUD labels -> native SAT */
    rts

/* Live score/high-score digit producers. */
.Lnq_title_emit_scores:
    lea     0x00FF011E, %a5           /* player score MSB byte */
    move.w  #0x0008, %d0
    movea.w %d0, %a4                  /* leftmost digit X (MSD) */
    moveq   #0, %d0
    movea.w %d0, %a6                  /* Y = 0x0000 */
    bsr     .Lnq_title_emit_digit_group
    lea     0x00FF011E, %a5           /* right-hand score column */
    move.w  #0x00E8, %d0
    movea.w %d0, %a4
    moveq   #0, %d0
    movea.w %d0, %a6
    bsr     .Lnq_title_emit_digit_group
    lea     0x00FF0142, %a5           /* high-score MSB byte */
    move.w  #0x0080, %d0
    movea.w %d0, %a4
    move.w  #0x0010, %d0
    movea.w %d0, %a6                  /* Y = 0x0010 */
    bsr     .Lnq_title_emit_digit_group
    /* Build 0270: native credit-line digits (retires the last 0x3B802 consumer).
     * Shown only when a credit exists (0x00FF0117 > 0), matching the arcade: the
     * credit records are parked off-screen in attract.  Two single digits at
     * their arcade layout (0x00FF0117 -> X 0x128 / Y 0xE8; 0x00FF0103 -> X 0x00 /
     * Y 0xE4), always shown when present (arcade count==1 = no zero suppression).
     * "CREDIT" label glyphs still render from the frontend scan. */
    tst.b   0x00FF0117
    beq.s   .Lnq_no_credits
    moveq   #0, %d1
    move.w  #0x00E8, %d2
    moveq   #0, %d3
    move.b  0x00FF0117, %d3
    andi.w  #0x000F, %d3
    addi.w  #0x002A, %d3
    move.w  #0x0128, %d4
    bsr     .Lnq_emit_entry
.Lnq_no_credits:
    rts

/* a5 = BCD MSB byte (read toward lower addresses), a4 = MSD X, a6 = Y.  Six
 * digits MSD-first, X stepping +8, glyph = 0x2A + nibble, passed in registers
 * to .Lnq_emit_entry (no scratch).  Reproduces the arcade 0x3B802 leading-zero
 * rule: leading zeros are suppressed (not emitted) until the first nonzero
 * digit, so the value is right-justified at fixed positions.  d7 low byte =
 * digit index, bit 8 = seen-nonzero flag. */
.Lnq_title_emit_digit_group:
    moveq   #0, %d7
.Ltdg_loop:
    move.w  %d7, %d0
    andi.w  #0x00FF, %d0              /* index */
    lsr.w   #1, %d0                   /* byte offset from MSB */
    movea.l %a5, %a0
    suba.w  %d0, %a0
    moveq   #0, %d0
    move.b  (%a0), %d0                /* live BCD byte */
    btst    #0, %d7
    bne.s   .Ltdg_low
    lsr.w   #4, %d0                   /* high nibble on even index */
.Ltdg_low:
    andi.w  #0x000F, %d0             /* digit value */
    btst    #8, %d7                  /* already seen a nonzero digit? */
    bne.s   .Ltdg_show
    tst.w   %d0
    beq.s   .Ltdg_suppress           /* leading zero -> suppress (emit nothing) */
.Ltdg_show:
    bset    #8, %d7
    addi.w  #0x002A, %d0             /* digit -> glyph code */
    move.w  %d0, %d3
    move.l  %a6, %d2                 /* Y */
    move.l  %a4, %d4                 /* X */
    moveq   #0, %d1                  /* attr */
    move.w  %d7, -(%sp)
    bsr     .Lnq_emit_entry
    move.w  (%sp)+, %d7
.Ltdg_suppress:
    addq.l  #8, %a4                  /* fixed position advances even when suppressed */
    addq.w  #1, %d7
    move.w  %d7, %d0
    andi.w  #0x00FF, %d0
    cmpi.w  #6, %d0
    blo.s   .Ltdg_loop
    rts

/* Build 0273: the Build-0272 write-then-clear workaround (.Lnq_hud_clear_records
 * + .Lnq_hud_owned_records) is DELETED.  The arcade HUD PC090OJ builders (0x3B8B0
 * and the 0x3B902 hook) are retired at the arcade-code boundary, so no HUD record
 * is produced and nothing needs clearing. */

    .align 2
/* Fixed frontend HUD text as a semantic glyph sequence: {Y, X, glyph_code},
 * letters and symbols only (codes >= 0x34); all numeric digits are produced live
 * above.  These values are the exact object-RAM label records the arcade builder
 * formerly wrote; .Lnq_emit_entry applies the same transform as the retired scan
 * path, so native output reproduces the former labels byte-for-byte.
 * 0xFFFF Y terminates. */
.Lnq_title_labels:
    /* Shared later-frontend labels retain their established native producer.
     * The title-active path above never reaches this table. */
    .include "../../build/rastan-direct/native_frontend_labels.inc"
.endif
.Lnq_gameplay:
    movem.l %d0-%d7/%a0-%a3, -(%sp)
    move.l  %a4, -(%sp)
    /* pc090oj_ctrl_shadow can only be changed by the arcade control producer.
     * This finalizer is one uninterrupted 68000 call, so cache its value once
     * for every gameplay lane entry in this pass. */
    moveq   #0, %d0
    move.w  pc090oj_ctrl_shadow, %d0
    swap    %d0
    movea.l %d0, %a4
    lea     staged_sprite_sat, %a3
    tst.w   pc090oj_sat_bank
    beq.s   .Lnq_bank_ok
    lea     staged_sprite_sat_b, %a3
.Lnq_bank_ok:
.if RASTAN_GAMEPLAY_HUD_SPRITES == 2
    bsr     .Lnq_project_p1_hud
.endif
    lea     sprite_tile_resident_code, %a2
    lea     pc090oj_cell_used, %a1
    clr.l   (%a1)+
    clr.l   (%a1)+
    clr.l   (%a1)+
    clr.l   (%a1)+
    moveq   #0, %d5

    lea     native_queue_hud, %a0
    move.w  native_hud_count, %d6
    bsr     .Lnq_emit_lane
    lea     native_queue_front_effect, %a0
    move.w  native_front_effect_count, %d6
    bsr     .Lnq_emit_lane
    lea     native_queue_player_front, %a0
    move.w  native_player_front_count, %d6
    bsr     .Lnq_emit_lane
    lea     native_queue_middle, %a0
    move.w  native_middle_count, %d6
    bsr     .Lnq_emit_lane
    lea     native_queue_player_body, %a0
    move.w  native_player_body_count, %d6
    bsr     .Lnq_emit_lane
    lea     native_queue_back_enemy, %a0
    move.w  native_back_enemy_count, %d6
    bsr     .Lnq_emit_lane
    /* Direct-native 0x5A502 attract/demo GAME OVER row -- owned here in the
     * gameplay finalizer under its exact original 0x05104E state gate, appended
     * after the native lanes (shares this pass's a3/a2/a1/d5 SAT context). */
    bsr     .Lnq_gameover_emit
    move.l  (%sp)+, %a4
    bra     .Lnq_done_scan

.if RASTAN_GAMEPLAY_HUD_SPRITES == 2
.Lnq_project_p1_hud:
.if RASTAN_DIAG_SCORE_METRIC
    /* Build 0338: gameplay HUD shows the diagnostic metric as the P1 score (memory-to-memory, no regs). */
    move.b  diag_score_bcd, 0x00FF011E
    move.b  diag_score_bcd+1, 0x00FF011F
    move.b  diag_score_bcd+2, 0x00FF0120
.endif
    movem.l %d0-%d7/%a0-%a3/%a6, -(%sp)
    clr.w   native_hud_count
    move.b  #NATIVE_LANE_HUD, native_sprite_lane+1
    bsr     native_sprite_fast_context
    movea.l #0x00FF011E, %a0
    clr.w   %d5

    moveq   #0, %d1
    move.b  (%a0), %d1
    lsr.b   #4, %d1
    andi.w  #0x000F, %d1
    moveq   #0x08, %d4
    bsr     .Lnq_emit_hud_digit

    moveq   #0, %d1
    move.b  (%a0), %d1
    andi.w  #0x000F, %d1
    moveq   #0x10, %d4
    bsr     .Lnq_emit_hud_digit
    subq.l  #1, %a0

    moveq   #0, %d1
    move.b  (%a0), %d1
    lsr.b   #4, %d1
    andi.w  #0x000F, %d1
    moveq   #0x18, %d4
    bsr     .Lnq_emit_hud_digit

    moveq   #0, %d1
    move.b  (%a0), %d1
    andi.w  #0x000F, %d1
    moveq   #0x20, %d4
    bsr     .Lnq_emit_hud_digit
    subq.l  #1, %a0

    moveq   #0, %d1
    move.b  (%a0), %d1
    lsr.b   #4, %d1
    andi.w  #0x000F, %d1
    moveq   #0x28, %d4
    bsr     .Lnq_emit_hud_digit

    moveq   #0, %d1
    move.b  (%a0), %d1
    andi.w  #0x000F, %d1
    moveq   #0x30, %d4
    bsr     .Lnq_emit_hud_digit

    moveq   #PC090OJ_HUD_P1_PROFILE_LINE, %d1
    move.w  #0x0010, %d2
    move.w  #0xD039, %d3            /* HUD-white + direct identity + fixed-screen bounds */
    move.w  #0x0040, %d4
    bsr     native_sprite_emit_fast
    moveq   #PC090OJ_HUD_P1_PROFILE_LINE, %d1
    move.w  #0x0010, %d2
    move.w  #0xD048, %d3            /* HUD-white + direct identity + fixed-screen bounds */
    move.w  #0x0028, %d4
    bsr     native_sprite_emit_fast
    moveq   #PC090OJ_HUD_P1_PROFILE_LINE, %d1
    move.w  #0x0010, %d2
    move.w  #0xD046, %d3            /* HUD-white + direct identity + fixed-screen bounds */
    move.w  #0x0038, %d4
    bsr     native_sprite_emit_fast
    movem.l (%sp)+, %d0-%d7/%a0-%a3/%a6
    rts
.Lnq_emit_hud_digit:
    move.w  #0x0010, %d2
    tst.w   %d5
    bne.s   .Lnq_digit_visible
    tst.w   %d1
    bne.s   .Lnq_digit_visible
    rts                                 /* leading zero was formerly queued off-screen and clipped */
.Lnq_digit_visible:
    moveq   #1, %d5
.Lnq_digit_ready:
    addi.w  #0x002A, %d1
    ori.w   #0xD000, %d1            /* HUD-white + direct identity + fixed-screen bounds */
    move.w  %d1, %d3
    moveq   #PC090OJ_HUD_SCORE_PROFILE_LINE, %d1
    bsr     native_sprite_emit_fast
    rts
.endif

    .global profile_native_lane_entry
profile_native_lane_entry:
.Lnq_emit_lane:
    tst.w   %d6
    beq     .Lnq_lane_done
    subq.w  #1, %d6
.Lnq_lane_loop:
    move.w  (%a0)+, %d1
    move.w  (%a0)+, %d2
    move.w  (%a0)+, %d3
    move.w  (%a0)+, %d4
    move.w  %d6, -(%sp)
    bsr     .Lnq_emit_entry_cached
    move.w  (%sp)+, %d6
    cmpi.w  #NATIVE_SAT_MAX, %d5
    bhs.s   .Lnq_lane_done
    dbra    %d6, .Lnq_lane_loop
.Lnq_lane_done:
    rts

    .global profile_native_final_piece_entry
profile_native_final_piece_entry:
.Lnq_emit_entry_cached:
    move.l  %a4, %d7                  /* cached ctrl word is in the upper half */
    bra.s   .Lnq_entry_ctrl_ready
.Lnq_emit_entry:
    move.w  pc090oj_ctrl_shadow, %d7  /* direct frontend callers keep exact semantics */
    swap    %d7
.Lnq_entry_ctrl_ready:
    move.w  %d3, %d0
    /* Build 0410: bit 12 is the generated-table direct-identity marker.  The
     * source code, nonblank status, and absence of a palette variant were all
     * proven by the independent frame-table verifier, so do not repeat those
     * dynamic decisions here.  Unmarked Level-A records retain the complete
     * runtime path below. */
    btst    #12, %d3
    bne.s   .Lnq_direct_identity
    btst    #13, %d3
    beq.s   .Lnq_source_identity_ready
    .global profile_native_pre_variant
profile_native_pre_variant:
    andi.w  #0x0FFF, %d0
    cmpi.w  #SPRITE_VARIANT_CELLS, %d0
    bhs     .Lnq_entry_skip
    add.w   %d0, %d0
    lea     pc090oj_variant_source_code, %a1
    move.w  0(%a1,%d0.w), %d0          /* source code only for blank/bbox provenance */
    bra.s   .Lnq_finalized_identity
    .global profile_native_pre_direct
profile_native_pre_direct:
.Lnq_direct_identity:
    andi.w  #0x0FFF, %d0
.Lnq_finalized_identity:
    beq     .Lnq_entry_skip
    bra.s   .Lnq_identity_validated
    .global profile_native_pre_dynamic
profile_native_pre_dynamic:
.Lnq_source_identity_ready:
    andi.w  #0x1FFF, %d0
    beq     .Lnq_entry_skip
    cmpi.w  #0x1000, %d0
    bhs     .Lnq_entry_skip
    move.w  %d0, %d6
    lsr.w   #3, %d6
    lea     pc090oj_blank_code_bitset, %a1
    move.b  0(%a1,%d6.w), %d6
    move.w  %d0, %d7
    andi.w  #0x0007, %d7
    btst    %d7, %d6
    bne     .Lnq_entry_skip
    /* Preserve the semantic-profile residency tag from caller code bit 15. Taken from
     * d3 directly (not a memory operand), so .Lnq_emit_entry is callable both by
     * the lane loader and directly with d1=attr/d2=Y/d3=code/d4=X in registers. */
    btst    #15, %d3
    sne     %d6
    btst    #13, %d3
    bne.s   .Lnq_keep_finalized_vi
    move.w  %d0, %d3
.Lnq_keep_finalized_vi:
    tst.b   %d6
    beq.s   .Lnq_no_hud_tag
    ori.w   #0x8000, %d3
.Lnq_no_hud_tag:

    .global profile_native_pre_validated
profile_native_pre_validated:
.Lnq_identity_validated:
    /* Keep the opaque-bounds source pointer live across coordinate geometry.
     * Build 0409 reconstructed this same source a second time below. */
    btst    #14, %d3                    /* fixed HUD producer proved viewport inclusion */
    bne.s   .Lnq_bbox_pointer_ready
    andi.l  #0x00000FFF, %d0
    lsl.l   #4, %d0
    lea     pc090oj_opaque_bbox, %a1
    adda.l  %d0, %a1

.Lnq_bbox_pointer_ready:
    .global profile_native_pre_pointer_ready
profile_native_pre_pointer_ready:
    andi.w  #0x01FF, %d2
    cmpi.w  #0x0140, %d2
    bls.s   .Lnq_y_ok
    subi.w  #0x0200, %d2
    .global profile_native_geometry_entry
profile_native_geometry_entry:
.Lnq_y_ok:
    andi.w  #0x01FF, %d4
    cmpi.w  #0x0140, %d4
    bls.s   .Lnq_x_ok
    subi.w  #0x0200, %d4
.Lnq_x_ok:
    swap    %d7
    move.w  %d7, %d6
    btst    #0, %d6
    bne.s   .Lnq_no_flip
    move.w  #PC090OJ_FLIP_X_TERM, %d6
    sub.w   %d4, %d6
    move.w  %d6, %d4
    move.w  #PC090OJ_FLIP_Y_TERM, %d6
    sub.w   %d2, %d6
    move.w  %d6, %d2
    eori.w  #0xC000, %d1
.Lnq_no_flip:
    addi.w  #PC090OJ_TO_GENESIS_X_OFFSET, %d4
    addi.w  #PC090OJ_TO_GENESIS_Y_OFFSET, %d2

    .global profile_native_bbox_entry
    profile_native_bbox_entry:
.Lnq_bbox_source_ready:
    btst    #14, %d3                    /* only fixed, visible P1 HUD cells carry this proof */
    bne     .Lnq_bbox_proven_visible
    move.w  %d1, %d7
    rol.w   #2, %d7                   /* attr V/H bits 15/14 -> index bits 1/0 */
    andi.w  #0x0003, %d7
    moveq   #0, %d0
    move.b  0(%a1,%d7.w), %d0
    moveq   #0, %d6
    move.b  4(%a1,%d7.w), %d6
    add.w   %d2, %d0
    add.w   %d2, %d6
    cmpi.w  #GENESIS_VIEWPORT_BOTTOM, %d0
    bge     .Lnq_entry_skip
    cmpi.w  #GENESIS_VIEWPORT_TOP, %d6
    blt     .Lnq_entry_skip
    moveq   #0, %d0
    move.b  8(%a1,%d7.w), %d0
    moveq   #0, %d6
    move.b  12(%a1,%d7.w), %d6
    add.w   %d4, %d0
    add.w   %d4, %d6
    cmpi.w  #GENESIS_VIEWPORT_RIGHT, %d0
    bge     .Lnq_entry_skip
    cmpi.w  #GENESIS_VIEWPORT_LEFT, %d6
    blt     .Lnq_entry_skip

.Lnq_bbox_proven_visible:
    .global profile_native_variant_entry
profile_native_variant_entry:
    /* Complete (code,bank) variant residency remap (generalized to ANY number of divergent code
     * blocks).  pc090oj_variant_group_base[code] (u16) is 0xFFFF for a non-divergent code, else the
     * variant-region cell base for the code's group; pc090oj_variant_bank_slot[effective_bank] is 0xFF
     * for a base bank, else the bank's ordinal within the group.  vi = group_base + ordinal.  The base
     * cell (baked at code*128) is the primary owner (e.g. lizardman 0x36 for 0xA73..0xAA2, flying_demon
     * 0x35 for 0x28E..0x2A8); variant banks (chimera 0x34 / four_armed 0x3A / burst 0x30) select an
     * appended cell.  Bounded O(1): one u16 table read + one byte read.  No runtime recolor; variant
     * bytes are pre-transformed offline.  Base bank and every non-divergent code are untouched. */
    btst    #12, %d3                    /* direct frame already proved base identity */
    bne.s   .Lnq_no_variant
    btst    #13, %d3                    /* native frame already baked canonical vi */
    bne.s   .Lnq_no_variant
    move.w  %d3, %d0
    andi.w  #0x0FFF, %d0
    add.w   %d0, %d0
    lea     pc090oj_variant_group_base, %a1
    move.w  0(%a1,%d0.w), %d6           /* d6 = group base (0xFFFF = not divergent) */
    cmpi.w  #0xFFFF, %d6
    beq.s   .Lnq_no_variant
    /* effective bank = (attr & 0x0F) | ((sprite_ctrl_shadow & 0x00E0) >> 1) -- the exact quantity the
     * palette-line lookup uses at .Lnq_hit, so the pixel variant matches its CRAM line. */
    moveq   #0, %d7
    move.b  native_sprite_lane, %d7
    move.w  %d1, %d0
    andi.w  #0x000F, %d0
    or.w    %d0, %d7
    andi.w  #0x007F, %d7
    lea     pc090oj_variant_bank_slot, %a1
    moveq   #0, %d0
    move.b  0(%a1,%d7.w), %d0           /* d0 = bank ordinal (0xFF = base bank, no variant) */
    cmpi.b  #0xFF, %d0
    beq.s   .Lnq_no_variant
    add.w   %d0, %d6                     /* vi = group_base + ordinal */
    ori.w   #SPRITE_VARIANT_KEY_MARK, %d6
    move.w  %d6, %d3                     /* residency key + worklist code = 0x2000 | vi */
.Lnq_no_variant:

    /* Exact O(1) reverse lookup. Normalize the semantic-profile bit-15 tag to
     * bit 12 (or a variant key into the free SPRITE_VARIANT_KEY_NORM range), then
     * perform one directory and one leaf access. */
    move.w  %d3, %d0
    btst    #13, %d3
    bne.s   .Lnq_reverse_key_variant
    andi.w  #0x0FFF, %d0
    btst    #15, %d3
    beq.s   .Lnq_reverse_key_ready
    ori.w   #0x1000, %d0
    bra.s   .Lnq_reverse_key_ready
.Lnq_reverse_key_variant:
    andi.w  #0x0FFF, %d0
    addi.w  #SPRITE_VARIANT_KEY_NORM, %d0
    .global profile_native_residency_entry
profile_native_residency_entry:
.Lnq_reverse_key_ready:
    move.w  %d0, %d6
    lsr.w   #4, %d6
    lea     sprite_tile_reverse_directory, %a1
    moveq   #0, %d7
    move.b  0(%a1,%d6.w), %d7
    cmpi.b  #0xFF, %d7
    beq.s   .Lnq_reverse_miss
    lsl.w   #4, %d7
    andi.w  #0x000F, %d0
    add.w   %d0, %d7
    lea     sprite_tile_reverse_pages, %a1
    moveq   #0, %d0
    move.b  0(%a1,%d7.w), %d0
    cmpi.b  #0xFF, %d0
    bne     .Lnq_hit
    .global profile_native_residency_miss
profile_native_residency_miss:
.Lnq_reverse_miss:
    move.w  %d1, -(%sp)
    /* Exact first-free allocation, preserved without the old 49-call scan.
     * Slots 0..47 occupy six complete used-bit bytes; slot 48 is bit 0 of
     * the seventh byte.  Scan bytes in ascending order, then bits in
     * ascending order, so the selected resident slot is unchanged. */
    moveq   #0, %d0
    lea     pc090oj_cell_used, %a1
    moveq   #5, %d1
.Lnq_vbyte_loop:
    cmpi.b  #0xFF, (%a1)+
    bne.s   .Lnq_vbyte_found
    addq.w  #8, %d0
    dbra    %d1, .Lnq_vbyte_loop
    btst    #0, (%a1)                  /* sole valid bit in byte 6: slot 48 */
    beq.s   .Lnq_vslot_found
.Lnq_vfull:
    move.w  (%sp)+, %d1
    addq.w  #1, pc090oj_dropped_count
    bra     .Lnq_entry_skip
.Lnq_vbyte_found:
    moveq   #0, %d6
    move.b  -1(%a1), %d6
    moveq   #0, %d7
    moveq   #7, %d1
.Lnq_vbit_loop:
    btst    %d7, %d6
    beq.s   .Lnq_vbit_found
    addq.w  #1, %d7
    dbra    %d1, .Lnq_vbit_loop
    bra.s   .Lnq_vfull                 /* impossible unless used bits changed */
.Lnq_vbit_found:
    add.w   %d7, %d0
.Lnq_vslot_found:
    add.w   %d0, %d0                   /* resident slot -> forward byte offset */
    .global profile_native_allocation_take
profile_native_allocation_take:
.Lnq_take:
    move.w  pc090oj_tile_dma_count, %d1
    cmpi.w  #12, %d1
    bhs.s   .Lnq_qfull
    lea     pc090oj_tile_dma_worklist, %a1
    lsl.w   #2, %d1
    adda.w  %d1, %a1
    move.w  %d0, %d1
    lsr.w   #1, %d1
    move.w  %d1, (%a1)+
    move.w  %d3, (%a1)
    addq.w  #1, pc090oj_tile_dma_count
    bsr     .Lnq_reverse_replace
    move.w  (%sp)+, %d1
    bra     .Lnq_hit
.Lnq_qfull:
    move.w  (%sp)+, %d1
    addq.w  #1, pc090oj_dropped_count
    bra     .Lnq_entry_skip

/* d0 = forward-table byte offset, d3 = new Build-0356 residency key,
 * a2 = sprite_tile_resident_code.  Preserve the caller's live registers.
 * Remove the old exact reverse mapping first, write the authoritative forward
 * slot, then install the new reverse mapping. */
.Lnq_reverse_replace:
    movem.l %d0-%d2/%d6-%d7/%a0-%a1, -(%sp)
    move.w  0(%a2,%d0.w), %d6
    beq.s   .Lnq_reverse_install_forward

    move.w  %d6, %d1
    btst    #13, %d6
    bne.s   .Lnq_reverse_old_key_variant
    andi.w  #0x0FFF, %d1
    btst    #15, %d6
    beq.s   .Lnq_reverse_old_key_ready
    ori.w   #0x1000, %d1
    bra.s   .Lnq_reverse_old_key_ready
.Lnq_reverse_old_key_variant:
    andi.w  #0x0FFF, %d1
    addi.w  #SPRITE_VARIANT_KEY_NORM, %d1
.Lnq_reverse_old_key_ready:
    move.w  %d1, %d7
    lsr.w   #4, %d7
    lea     sprite_tile_reverse_directory, %a0
    moveq   #0, %d2
    move.b  0(%a0,%d7.w), %d2
    cmpi.b  #0xFF, %d2
    beq.s   .Lnq_reverse_install_forward
    andi.w  #0x000F, %d1
    move.w  %d2, %d6
    lsl.w   #4, %d6
    add.w   %d1, %d6
    lea     sprite_tile_reverse_pages, %a1
    move.b  #0xFF, 0(%a1,%d6.w)
    lea     sprite_tile_reverse_page_refcount, %a1
    subq.b  #1, 0(%a1,%d2.w)
    bne.s   .Lnq_reverse_install_forward

    /* Last key in this group: release the page back to the bounded pool. */
    move.b  #0xFF, 0(%a0,%d7.w)
    move.w  sprite_tile_reverse_free_count, %d6
    lea     sprite_tile_reverse_free_pages, %a1
    move.b  %d2, 0(%a1,%d6.w)
    addq.w  #1, %d6
    move.w  %d6, sprite_tile_reverse_free_count

.Lnq_reverse_install_forward:
    move.w  %d3, 0(%a2,%d0.w)
    move.w  %d3, %d1
    btst    #13, %d3
    bne.s   .Lnq_reverse_new_key_variant
    andi.w  #0x0FFF, %d1
    btst    #15, %d3
    beq.s   .Lnq_reverse_new_key_ready
    ori.w   #0x1000, %d1
    bra.s   .Lnq_reverse_new_key_ready
.Lnq_reverse_new_key_variant:
    andi.w  #0x0FFF, %d1
    addi.w  #SPRITE_VARIANT_KEY_NORM, %d1
.Lnq_reverse_new_key_ready:
    move.w  %d1, %d7
    lsr.w   #4, %d7
    lea     sprite_tile_reverse_directory, %a0
    moveq   #0, %d2
    move.b  0(%a0,%d7.w), %d2
    cmpi.b  #0xFF, %d2
    bne.s   .Lnq_reverse_have_page

    move.w  sprite_tile_reverse_free_count, %d6
    subq.w  #1, %d6
    move.w  %d6, sprite_tile_reverse_free_count
    lea     sprite_tile_reverse_free_pages, %a1
    moveq   #0, %d2
    move.b  0(%a1,%d6.w), %d2
    move.b  %d2, 0(%a0,%d7.w)
.Lnq_reverse_have_page:
    andi.w  #0x000F, %d1
    move.w  %d2, %d6
    lsl.w   #4, %d6
    add.w   %d1, %d6
    lea     sprite_tile_reverse_pages, %a1
    move.b  %d0, 0(%a1,%d6.w)
    lea     sprite_tile_reverse_page_refcount, %a1
    addq.b  #1, 0(%a1,%d2.w)
    movem.l (%sp)+, %d0-%d2/%d6-%d7/%a0-%a1
    rts

    .global profile_native_sat_entry
profile_native_sat_entry:
.Lnq_hit:
    /* Build 0411: retain the live resident slot in d6.  The old path pushed it
     * twice and reconstructed the used-bit address from stack temporaries. */
    move.w  %d0, %d6
    move.w  %d0, %d7
    lea     pc090oj_cell_used, %a1
    lsr.w   #4, %d7
    adda.w  %d7, %a1
    lsr.w   #1, %d0
    andi.w  #7, %d0
    bset    %d0, (%a1)
    /* (value & 0x1ff + bias) & 0x1ff equals (value + bias) & 0x1ff. */
    .global profile_native_sat_y
profile_native_sat_y:
    move.w  %d2, %d0
    addi.w  #PC090OJ_SAT_Y_BIAS, %d0
    andi.w  #0x01FF, %d0
    move.w  %d0, (%a3)+
    .global profile_native_sat_link
profile_native_sat_link:
    move.w  %d5, %d0
    addq.w  #1, %d0
    ori.w   #0x0500, %d0
    move.w  %d0, (%a3)+
    /* Arcade V/H bits 15/14 map directly to Genesis bits 12/11 after a
     * three-place shift.  This replaces two per-entry branch trees. */
    .global profile_native_sat_attr
profile_native_sat_attr:
    move.w  %d1, %d0
    lsr.w   #3, %d0
    andi.w  #0x1800, %d0
    ori.w   #0x8000, %d0
    /* Compose final palette bits now. Bit 15 marks the generated semantic
     * GAME OVER/HUD profile asset; its object-specific line travels in d1 and
     * comes from the generated current-Test constants above, not bank 0x30. */
    moveq   #0, %d7
    btst    #15, %d3
    beq.s   .Lnq_palette_lookup
    move.w  %d1, %d7
    andi.w  #0x0003, %d7
    bra.s   .Lnq_palette_ready
.Lnq_palette_lookup:
    move.w  %d1, %d2
    andi.w  #0x000F, %d2
    moveq   #0, %d7
    move.b  native_sprite_lane, %d7
    or.w    %d7, %d2
    movea.l current_sprite_palette_map, %a1
    moveq   #0, %d7
    move.b  0(%a1,%d2.w), %d7
.Lnq_palette_ready:
    add.w   %d7, %d7
    lea     .Lnq_sat_palette_bits, %a1
    move.w  0(%a1,%d7.w), %d7
    or.w    %d7, %d0
    move.w  %d6, %d2
    add.w   %d2, %d2
    addi.w  #SPRITE_TILE_BASE, %d2
    or.w    %d2, %d0
    move.w  %d0, (%a3)+
    .global profile_native_sat_x
profile_native_sat_x:
    move.w  %d4, %d0
    addi.w  #PC090OJ_SAT_X_BIAS, %d0
    andi.w  #0x01FF, %d0
    move.w  %d0, (%a3)+
    .global profile_native_sat_count
profile_native_sat_count:
    addq.w  #1, %d5
    .global profile_native_piece_return
profile_native_piece_return:
.Lnq_entry_skip:
    rts

    .align 2
.Lnq_sat_palette_bits:
    .word 0x0000, 0x2000, 0x4000, 0x6000

    .global profile_native_finalizer_done
profile_native_finalizer_done:
.Lnq_done_scan:
    tst.w   %d5
    bne.s   .Lnq_have
    clr.w   (%a3)+
    clr.w   (%a3)+
    clr.w   (%a3)+
    clr.w   (%a3)+
    bra.s   .Lnq_store
.Lnq_have:
    move.w  -6(%a3), %d0
    andi.w  #0xFF80, %d0
    move.w  %d0, -6(%a3)
.Lnq_store:
    move.w  %d5, pc090oj_emitted_count
    move.w  #1, pc090oj_sat_frame_ready
    move.w  #1, pc090oj_sat_dirty
    movem.l (%sp)+, %d0-%d7/%a0-%a3
    rts

/* Frontend / non-gameplay native finalizer (PC090OJ final teardown).  The former
 * .Lnq_frontend_object_scan + its 256-record object-RAM loop, decoder, and
 * residency tail are REMOVED; every frontend sprite is produced by native
 * Genesis owners.  This mirrors .Lnq_title's setup plus the transient item/effect
 * family, then hands off to the shared native finalizer .Lnq_done_scan.  Reached
 * for scene 0 stage!=0 and scene 2 from pc090oj_native_emit_pass. */
.Lnq_frontend_native:
    tst.w   transient_items_active
    beq     .Lnq_title
    movem.l %d0-%d7/%a0-%a3, -(%sp)
    movem.l %a4-%a6, -(%sp)
    bsr     genesistan_hud_activate_frontend
    bsr     genesistan_hud_link_transient
    lea     staged_sprite_sat, %a3
    tst.w   pc090oj_sat_bank
    beq.s   .Lnqfn_bank_ok
    lea     staged_sprite_sat_b, %a3
.Lnqfn_bank_ok:
    adda.w  #(30 * 8), %a3
    lea     sprite_tile_resident_code, %a2
    lea     pc090oj_cell_used, %a1     /* per-frame referenced-cell bitmap */
    move.w  #0xFFFF, (%a1)+           /* HUD cells 0..15 reserved */
    move.b  #0x0F, (%a1)+             /* HUD cells 16..19 reserved */
    clr.b   (%a1)+
    clr.l   (%a1)+
    clr.l   (%a1)+
    clr.l   (%a1)+
    moveq   #30, %d5                   /* append after shared HUD records */
    bsr     .Lnq_transient_items_emit    /* frontend-direct treasure/item family */
    movem.l (%sp)+, %a4-%a6
    bra     .Lnq_done_scan

/* VBlank entry. Every frontend state selects the same change-driven FULL HUD;
 * gameplay retains the established REDUCED_P1 finalizer. */
vdp_prepare_sprites:
    cmpi.b  #PC090OJ_SCENE_GAMEPLAY_ID, genesistan_current_scene_id
    beq.s   .Lvps_gameplay
    bsr     genesistan_hud_prepare_frontend
    tst.w   transient_items_active
    beq.s   .Lvps_done
    tst.w   pc090oj_sat_frame_ready
    bne.s   .Lvps_done
    bsr     pc090oj_native_emit_pass
    rts
.Lvps_gameplay:
    tst.w   pc090oj_sat_frame_ready
    bne.s   .Lvps_done
    bsr     pc090oj_native_emit_pass
.Lvps_done:
    rts

/* VBlank commit: pattern uploads, then publish+DMA the finished bank.       */
vdp_commit_sprites:
vdp_commit_sprites_vram:
    movem.l %d0-%d7/%a0-%a6, -(%sp)
    bsr     .Lvcs_tile_dma
    tst.w   pc090oj_sat_frame_ready
    beq.s   .Lvcs_commit_done
    move.w  pc090oj_sat_bank, pc090oj_sat_front
    eori.w  #1, pc090oj_sat_bank
    clr.w   pc090oj_sat_frame_ready
    bsr     .Lvcs_sat_dma
    clr.w   pc090oj_sat_dirty
.Lvcs_commit_done:
    movem.l (%sp)+, %d0-%d7/%a0-%a6
    rts

/* PC090OJ final teardown: .Lpc090oj_decode_record (virtual-record word decode,
 * clip, flip, code, colbank) REMOVED with pc090oj_object_ram and the frontend scan. */

/*
 * Precomputed tile-DMA worklist commit.  Bounded by pc090oj_tile_dma_count,
 * skips canceled entries (code 0xFFFF), updates slot residency only after the
 * DMA, and resets the reservation map + count at the end of the interval.
 */
.Lvcs_tile_dma:
    move.w  pc090oj_tile_dma_count, %d7
    beq     .Lvcs_tile_reset
    moveq   #0, %d5
.Lvcs_tile_loop:
    move.w  %d5, %d0
    lsl.w   #2, %d0
    lea     pc090oj_tile_dma_worklist, %a0
    adda.w  %d0, %a0
    move.w  (%a0), %d4                  /* slot */
    move.w  2(%a0), %d6                /* code (0xFFFF = canceled) */
    cmpi.w  #0xFFFF, %d6
    beq     .Lvcs_tile_next

	    move.w  %d6, %d0
	    /* Build 0381: variant key (bit 13) -> appended (code,bank) variant cell. */
	    btst    #13, %d6
	    beq.s   .Lvcs_tile_src_notvar
	    andi.w  #0x0FFF, %d0                 /* vi (0..SPRITE_VARIANT_CELLS-1) */
	    mulu.w  #128, %d0
	    lea     rastan_pc090oj, %a1
	    adda.l  #SPRITE_VARIANT_REGION_OFF, %a1
	    adda.l  %d0, %a1
	    bra.s   .Lvcs_tile_src_ready
	.Lvcs_tile_src_notvar:
	    andi.w  #0x0FFF, %d0
	    btst    #15, %d6
	    beq.s   .Lvcs_tile_src_normal
	    move.w  %d0, %d3
	    subi.w  #0x002A, %d3
	    mulu.w  #128, %d3
	    lea     rastan_pc090oj_semantic_profile, %a1
	    adda.l  %d3, %a1
	    bra.s   .Lvcs_tile_src_ready
	.Lvcs_tile_src_normal:
	    mulu.w  #128, %d0
	    lea     rastan_pc090oj, %a1
	    adda.l  %d0, %a1
	.Lvcs_tile_src_ready:
    /* Build 0345: issue the sprite-cell VRAM DMA through the dma.s-owned primitive instead of an
     * inline register program.  in: a0 = 68k source (byte), d0 = VRAM byte dest, d1 = word count
     * (64 words = one 128-byte sprite cell group).  Preserves d4-d7 (slot/index/code/count) and a2.
     * Build 0418 uses the checked autoinc=2 entry because this source is ROM-backed; the SAT and
     * strided-column WRAM callers retain the noai entry. */
    movea.l %a1, %a0
    move.w  %d4, %d0
    lsl.w   #2, %d0
    addi.w  #SPRITE_TILE_BASE, %d0
    lsl.l   #5, %d0
    moveq   #64, %d1
    bsr     vdp_dma_words_to_vram
    move.w  %d4, %d0
    add.w   %d0, %d0
    lea     sprite_tile_resident_code, %a1
    move.w  %d6, 0(%a1,%d0.w)
.Lvcs_tile_next:
    addq.w  #1, %d5
    cmp.w   %d7, %d5
    blo     .Lvcs_tile_loop
.Lvcs_tile_reset:
    /* Reset only the slots actually reserved this interval (d7 = count, still
     * live), so a stable no-work frame (count 0) does zero reset work. */
    tst.w   %d7
    beq.s   .Lvcs_tile_reset_done
    moveq   #0, %d5
.Lvcs_tile_reset_loop:
    move.w  %d5, %d0
    lsl.w   #2, %d0
    lea     pc090oj_tile_dma_worklist, %a0
    adda.w  %d0, %a0
    moveq   #0, %d0
    move.w  (%a0), %d0                  /* reserved slot for this entry */
    lea     worklist_entry_for_slot, %a1
    move.b  #0xFF, 0(%a1,%d0.w)
    addq.w  #1, %d5
    cmp.w   %d7, %d5
    blo.s   .Lvcs_tile_reset_loop
.Lvcs_tile_reset_done:
    clr.w   pc090oj_tile_dma_count
    rts

/* SAT DMA: whole 80-slot table every frame (640 B = 320 words) to VRAM 0xF800.
 * Build 0345: issued through the dma.s-owned primitive (a0=source, d0=dest byte, d1=word count). */
.Lvcs_sat_dma:
    lea     staged_sprite_sat, %a0
    tst.w   pc090oj_sat_front
    beq.s   .Lsat_src_ok
    lea     staged_sprite_sat_b, %a0
.Lsat_src_ok:
    move.l  #0x0000F800, %d0          /* VRAM SAT base */
    move.w  #(80 * 4), %d1            /* whole table: 320 words = 640 bytes */
    bsr     dma_words_to_vram_noai
    rts

/* ------------------------------------------------------------------------- */
/* VRAM DMA self-test                                                        */
/* ------------------------------------------------------------------------- */

genesistan_pc090oj_dma_self_test:
    movem.l %d0-%d7/%a0-%a6, -(%sp)

    /* Stack buffer (128 bytes) */
    lea     -128(%sp), %sp
    movea.l %sp, %a6

    /* DMA source: rastan_pc090oj + 0x80, len 64 words, dest VRAM 0x8000 */
    lea     rastan_pc090oj+0x80, %a1
    move.l  %a1, %d0
    lsr.l   #1, %d0

    movea.l #VDP_CTRL, %a3
    move.w  #0x9340, (%a3)
    move.w  #0x9400, (%a3)

    move.w  %d0, %d1
    andi.w  #0x00FF, %d1
    ori.w   #0x9500, %d1
    move.w  %d1, (%a3)

    move.l  %d0, %d1
    lsr.l   #8, %d1
    andi.w  #0x00FF, %d1
    ori.w   #0x9600, %d1
    move.w  %d1, (%a3)

    move.l  %d0, %d1
    lsr.l   #8, %d1
    lsr.l   #8, %d1
    andi.w  #0x007F, %d1
    ori.w   #0x9700, %d1
    move.w  %d1, (%a3)

    move.l  #0x00008000, %d0
    move.l  %d0, %d1
    andi.l  #0x00003FFF, %d1
    swap    %d1
    move.l  %d0, %d2
    lsr.l   #8, %d2
    lsr.l   #6, %d2
    andi.l  #0x00000003, %d2
    ori.l   #0x40000080, %d1
    or.l    %d2, %d1
    move.l  %d1, (%a3)

    /* Read back VRAM 0x8000..0x807F into stack buffer */
    move.l  #0x00008000, %d0
    move.l  %d0, %d1
    andi.l  #0x00003FFF, %d1
    swap    %d1
    move.l  %d0, %d2
    lsr.l   #8, %d2
    lsr.l   #6, %d2
    andi.l  #0x00000003, %d2
    or.l    %d2, %d1                 /* VRAM read command (no write/dma bits) */
    move.l  %d1, (%a3)

    movea.l #VDP_DATA, %a4
    move.w  #(64 - 1), %d0
.Lpc090oj_dma_read_loop:
    move.w  (%a4), (%a6)+
    dbra    %d0, .Lpc090oj_dma_read_loop

    /* Compare 64 words */
    lea     rastan_pc090oj+0x80, %a0
    movea.l %sp, %a1
    moveq   #0, %d6
    move.w  #(64 - 1), %d0
.Lpc090oj_dma_cmp_loop:
    move.w  (%a0)+, %d1
    move.w  (%a1)+, %d2
    cmp.w   %d1, %d2
    bne.s   .Lpc090oj_dma_fail
    addq.w  #1, %d6
    dbra    %d0, .Lpc090oj_dma_cmp_loop

    lea     128(%sp), %sp
    movem.l (%sp)+, %d0-%d7/%a0-%a6
    rts

.Lpc090oj_dma_fail:
    move.w  %d6, pc090oj_dma_test_mismatch_offset
    move.w  %d1, pc090oj_dma_test_expected_word
    move.w  %d2, pc090oj_dma_test_actual_word

    /* copy full 128-byte snapshot */
    movea.l %sp, %a0
    lea     pc090oj_dma_test_actual_buffer, %a1
    move.w  #(128/2 - 1), %d0
.Lpc090oj_dma_copy_buf:
    move.w  (%a0)+, (%a1)+
    dbra    %d0, .Lpc090oj_dma_copy_buf

    move.w  #0x6F0E, pc090oj_dma_test_fired_flag

.Lpc090oj_dma_test_halt:
    move.b  pc090oj_dma_test_heartbeat, %d0
    addq.b  #1, %d0
    move.b  %d0, pc090oj_dma_test_heartbeat
    bra     .Lpc090oj_dma_test_halt

/* ------------------------------------------------------------------------- */
/* BSS                                                                        */
/* ------------------------------------------------------------------------- */

    .section .bss
    .align 2

/* N1 shadow SAT double buffer (final Genesis SAT format, link-ordered). */
staged_sprite_sat:
    .space (80 * 8)
staged_sprite_sat_b:
    .space (80 * 8)
pc090oj_sat_bank:
    .word 0
pc090oj_sat_front:
    .word 0
pc090oj_sat_frame_ready:
    .word 0
current_sprite_palette_map:
    .space 4
/* Per-frame referenced-cell bitmap (49 live bits; rounded storage). */
pc090oj_cell_used:
    .space 16
/* Code-keyed residency tags: 49 fully-associative cells (tiles 1339..1534). */
sprite_tile_resident_code:
    .space (NATIVE_CELLS * 2)
/* Bounded VBlank pattern-upload queue: 12 x {word cell, word code}. */
pc090oj_tile_dma_worklist:
    .space (12 * 4)
pc090oj_tile_dma_count:
    .word 0
/* Item family lifetime only. Static content is generated and A5+0x10EE is the
 * sole scroll authority. */
transient_items_active:
    .word 0
/* Private packed dispatch word: high byte is normalized
 * ((sprite_ctrl & 0x00E0) >> 1), low byte is the semantic lane.  Packing the
 * two frame-private values preserves every established WRAM symbol address. */
native_sprite_lane:
    .word 0
native_hud_count:
    .word 0
native_front_effect_count:
    .word 0
native_player_front_count:
    .word 0
native_middle_count:
    .word 0
native_player_body_count:
    .word 0
native_back_enemy_count:
    .word 0
native_queue_hud:
    .space (NATIVE_HUD_BOUND * NATIVE_QUEUE_ENTRY_BYTES)
native_queue_hud_end:
native_queue_front_effect:
    .space (NATIVE_FRONT_EFFECT_BOUND * NATIVE_QUEUE_ENTRY_BYTES)
native_queue_front_effect_end:
native_queue_player_front:
    .space (NATIVE_PLAYER_FRONT_BOUND * NATIVE_QUEUE_ENTRY_BYTES)
native_queue_player_front_end:
native_queue_middle:
    .space (NATIVE_MIDDLE_BOUND * NATIVE_QUEUE_ENTRY_BYTES)
native_queue_middle_end:
native_queue_player_body:
    .space (NATIVE_PLAYER_BODY_BOUND * NATIVE_QUEUE_ENTRY_BYTES)
native_queue_player_body_end:
native_queue_back_enemy:
    .space (NATIVE_BACK_ENEMY_BOUND * NATIVE_QUEUE_ENTRY_BYTES)
native_queue_back_enemy_end:
    .align 2
/* Native sprite-control shadows: pc090oj_ctrl_shadow is the global-flip control;
 * pc090oj_sprite_ctrl_shadow supplies the dynamic colbank to emit-time lookup.
 * Both are live native state (historical name only), NOT compatibility RAM. */
pc090oj_ctrl_shadow:
    .word 0
pc090oj_sprite_ctrl_shadow:
    .word 0
/* Native SAT finalizer state (shared by title/gameplay/frontend). */
pc090oj_emitted_count:
    .word 0
pc090oj_dropped_count:
    .word 0
native_player_fallback_count:
    .word 0
native_generic_fallback_count:
    .word 0
native_specialized_hit_count:
    .word 0
native_player_piece_adapter_count:
    .word 0
pc090oj_sat_dirty:
    .word 0
/* Audit-guard + DMA self-test diagnostics (retained consumers). */
audit_guard_caller_pc:
    .long 0
audit_guard_register_snapshot:
    .space (16 * 4)
audit_guard_vcount:
    .word 0
audit_guard_fired_flag:
    .word 0
audit_guard_heartbeat:
    .word 0
    .align 2

/* Native tile-DMA scratch (historical name; live consumer at the tile-DMA
 * commit path). */
worklist_entry_for_slot:
    .space NATIVE_CELLS
    .align 2

/* Exact two-level reverse residency index.  The directory and leaf pages are
 * contiguous so bootstrap initialization can invalidate them in one loop. */
sprite_tile_reverse_directory:
    .space NATIVE_REVERSE_DIRECTORY_BYTES
sprite_tile_reverse_pages:
    .space (NATIVE_REVERSE_PAGE_BYTES * NATIVE_REVERSE_PAGE_COUNT)
sprite_tile_reverse_page_refcount:
    .space NATIVE_REVERSE_PAGE_COUNT
sprite_tile_reverse_free_pages:
    .space NATIVE_REVERSE_PAGE_COUNT
    .align 2
sprite_tile_reverse_free_count:
    .word 0

    .section .bss.patcher
    .balign 2
pc090oj_dma_test_fired_flag:
    .word 0
pc090oj_dma_test_mismatch_offset:
    .word 0
pc090oj_dma_test_expected_word:
    .word 0
pc090oj_dma_test_actual_word:
    .word 0
pc090oj_dma_test_actual_buffer:
    .space 128
pc090oj_dma_test_heartbeat:
    .byte 0
